bool same_imagepaths(const std::vector<std::shared_ptr<::cw::image::ImageInfo>>& left,
                     const std::vector<std::shared_ptr<::cw::image::ImageInfo>>& right)
{
    if (left.size() != right.size()) return false;
    for (std::size_t i = 0; i < left.size(); ++i) {
        if (!left[i] || !right[i]) {
            if (left[i] != right[i]) return false;
            continue;
        }
        if (left[i]->m_path != right[i]->m_path ||
            left[i]->m_pcnumber != right[i]->m_pcnumber ||
            left[i]->m_postype != right[i]->m_postype) return false;
    }
    return true;
}
