Integer dice_roll(Integer sides)
{
    if (sides <= 1) return 1;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_dice) return ::cw::g_cwpy->m_dice->roll(1, sides);
    static thread_local std::mt19937 engine{std::random_device{}()};
    std::uniform_int_distribution<Integer> dist(1, sides);
    return dist(engine);
}

// ポップアップの合成処理を共通化し、座標と寸法は所有者の描画面の座標系を使う。
// 行ごとにクリッピングし、長いラベルが隣のコントロールへはみ出さないようにする。
::cw::lib::Rect create_choice_popup_geometry(
    ::cw::lib::Size surface_size,const std::vector<String>& labels,
    ::cw::lib::Rect anchor,int& cursor,int& first,const ::cw::lib::ui::FontStyle& font,
    int row_height,int max_rows,bool scroll_buttons=false,double metric_scale=1.0) {
    const auto px=[&](Integer n){return static_cast<Integer>(std::lround(n*metric_scale));};
    if(labels.empty()) return {};
    const int count=static_cast<int>(labels.size());cursor=std::clamp(cursor,0,count-1);
    const int rows=std::min({max_rows,count,std::max(1,static_cast<int>(surface_size.height)/row_height-2)});
    first=std::clamp(first,0,count-rows);first=std::clamp(first,std::max(0,cursor-rows+1),cursor);
    Integer width=anchor.width;
    for(const auto& item:labels)width=std::max(width,::cw::lib::ui::label_width(item,font.pixels,font.bold,font.face,font.italic)+px(12));
    width=std::min(width,surface_size.width);const int nav=scroll_buttons&&count>rows?static_cast<int>(px(16)):0;
    const Integer height=rows*row_height+2*nav,x=std::clamp<Integer>(anchor.x,0,surface_size.width-width);
    Integer y=anchor.y+anchor.height;if(y+height>surface_size.height&&anchor.y>=height)y=anchor.y-height;
    y=std::clamp<Integer>(y,0,surface_size.height-height);return {x,y,width,height};
}

void draw_create_choice_popup(::cw::dialog::DialogPresentation& result,
    const std::shared_ptr<::cw::lib::Surface>& surface,const std::vector<String>& labels,
    ::cw::lib::Rect anchor,int& cursor,int& first,const ::cw::lib::ui::FontStyle& font,
    int row_height,int max_rows,bool scroll_buttons=false,double metric_scale=1.0,bool paint=true) {
    const auto px=[&](Integer n){return static_cast<Integer>(std::lround(n*metric_scale));};
    using Action=::cw::dialog::DialogPresentationAction;
    if(labels.empty()) return;
    const int count=static_cast<int>(labels.size());
    const auto popup=create_choice_popup_geometry(surface->size,labels,anchor,cursor,first,font,row_height,max_rows,scroll_buttons,metric_scale);
    const int rows=std::min({max_rows,count,std::max(1,static_cast<int>(surface->size.height)/row_height-2)});
    const Integer width=popup.width;
    const int nav=scroll_buttons && count>rows?static_cast<int>(px(16)):0;
    const Integer height=popup.height,x=popup.x,y=popup.y;
    if(paint) ::cw::lib::ui::fill_rect(surface,popup,{255,255,255,255});
    result.wants_text_input=false;
    result.controls.clear();
    result.controls.push_back({Action::Cancel,-1,0,0,static_cast<float>(surface->size.width),static_cast<float>(surface->size.height),true});
    const auto hit=[&](int id,::cw::lib::Rect r,bool enabled,const String& text) {
        result.controls.push_back({Action::Auxiliary,id,static_cast<float>(r.x),static_cast<float>(r.y),
            static_cast<float>(r.width),static_cast<float>(r.height),enabled,false,text,text});
    };
    // 無効なスクロール矢印や一覧の枠へのクリックを、描画
    // 面全体の領域外クリック用キャンセル処理へ通さない。
    hit(97,popup,true,{});
    if(nav) for(int direction=0;direction<2;++direction) {
        const ::cw::lib::Rect r{x+px(1),y+(direction?height-nav:0),width-px(2),nav};
        const bool enabled=direction?cursor<count-1:cursor>0;
        if(paint) ::cw::lib::ui::fill_rect(surface,r,{240,240,240,255});
        for(int line=0;line<4;++line) {
            const int half=direction?3-line:line;
            if(paint) ::cw::lib::ui::fill_rect(surface,{r.x+r.width/2-px(half),r.y+px(6+line),px(2*half+1),px(1)},
                enabled?::cw::lib::Color{0,0,0,255}: ::cw::lib::Color{150,150,150,255});
        }
        hit(direction?99:98,r,enabled,direction?"下へスクロール":"上へスクロール");
    }
    for(int row=0;row<rows;++row) {
        const int item=first+row;
        const ::cw::lib::Rect r{x+px(2),y+nav+row*row_height+px(1),width-px(4),row_height-px(1)};
        if(paint) {
            auto clipped=std::make_shared<::cw::lib::Surface>();clipped->size={r.width,r.height};
            clipped->rgba.assign(static_cast<std::size_t>(r.width*r.height)*4,255);
            const auto selection=::cw::lib::ui::system_selection_colours();
            ::cw::lib::ui::fill_rect(clipped,{0,0,r.width,r.height},item==cursor?
                selection.background: ::cw::lib::Color{255,255,255,255});
            const auto color=item==cursor?std::tuple<Integer,Integer,Integer>{selection.text.r,selection.text.g,selection.text.b}:
                std::tuple<Integer,Integer,Integer>{0,0,0};
            const auto glyph=::cw::lib::ui::render_label(labels[item],font.pixels,font.bold,color,font.face,font.italic);
            if(glyph)::cw::lib::ui::blend_surface(clipped,glyph,px(3),std::max<Integer>(0,(r.height-glyph->size.height)/2));
            ::cw::lib::ui::blend_surface(surface,clipped,r.x,r.y);
        }
        hit(100+item,r,true,labels[item]);
    }
    if(paint) ::cw::lib::ui::draw_sunken_border(surface,popup);
}

