// 最終解像度のレイヤーは、Python の wx マスク合成処理を共通に使う。 Book
// に対する 1 ビットの AND/OR 合成は、透明な作業バッファーだけでは再現できない。
std::shared_ptr<::cw::lib::Surface> creator_portrait(
    std::vector<std::shared_ptr<::cw::image::ImageInfo>> infos,
    const std::shared_ptr<::cw::lib::Surface>& background,
    const NamePage::PortraitLoader& load,const String& basecardtype) {
    auto face=std::make_shared<::cw::lib::Bitmap>();
    static_cast<::cw::lib::Surface&>(*face)=*creator_canvas(creator_px(74),creator_px(94));
    if(background)::cw::lib::ui::blend_surface(face,background,0,0);
    if(::cw::util::is_face_variant_imageinfos(infos))
        infos=::cw::util::pick_up_basename_image(std::move(infos),false);
    for(const auto& info:infos) {
        if(!info || info->m_path.empty())continue;
        const auto raw=load(info->m_path);if(!raw)continue;
        auto original=std::make_shared<::cw::lib::Bitmap>();
        static_cast<::cw::lib::Surface&>(*original)=*raw;
        if(const auto source=std::dynamic_pointer_cast<::cw::lib::Bitmap>(raw))
            ::cw::util::copy_animated_wxbmp_info(source,original);
        else
            ::cw::lib::ui::inherit_surface_animation(original,raw);
        original=::cw::util::resolve_animated_wxbmp(original);
        const auto normalized=::cw::lib::ui::resource_surface_for_window(original);
        if(!normalized)continue;
        auto bitmap=std::make_shared<::cw::lib::Bitmap>();
        static_cast<::cw::lib::Surface&>(*bitmap)=*normalized;
        const auto base=info->calc_basecardposition_wx(
            {bitmap->size.width,bitmap->size.height},false,basecardtype,"NotCard");
        ::cw::imageretouch::wxblit_2bitbmp_to_card({},face,bitmap,base.x,base.y,true,original);
        ::cw::lib::ui::inherit_surface_animation(face,original);
    }
    return face;
}
std::set<String> creator_randomnames(const String& sex) {
    std::set<String> names;
    const String skin=::cw::g_cwpy?value_string(::cw::g_cwpy->m_skindir):String{};
    for(const auto& file:{String("CommonNames.txt"),sex.empty()?String{}:sex+"Names.txt"})
        if(!file.empty())names.merge(_read_names(::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(skin)/"Name"/file)));
    if(names.empty()) names=_get_randomnamefromexample(sex,
        ::cw::g_cwpy && ::cw::g_cwpy->m_setting?::cw::g_cwpy->m_setting->m_skintype:String{});
    return names;
}

struct YadoTextBlock {
    std::vector<std::shared_ptr<::cw::lib::Surface>> lines;
    Integer width{},height{},line_height{};
};
YadoTextBlock yado_text_block(const String& text,const ::cw::lib::ui::FontStyle& font) {
    YadoTextBlock block;
    const auto metrics=::cw::lib::ui::render_label("Mg",font.pixels,font.bold,{0,0,0},font.face,font.italic);
    block.line_height=std::max<Integer>(font.pixels,metrics?metrics->size.height:0);
    std::size_t start=0;
    do {
        const auto end=text.find('\n',start);
        auto line=text.substr(start,end==String::npos?String::npos:end-start);
        if(!line.empty() && line.back()=='\r') line.pop_back();
        auto image=::cw::lib::ui::render_label(line,font.pixels,font.bold,{0,0,0},font.face,font.italic);
        if(image) block.width=std::max(block.width,image->size.width);
        block.lines.push_back(std::move(image));
        if(end==String::npos) break;
        start=end+1;
    } while(start<=text.size());
    block.height=block.line_height*static_cast<Integer>(block.lines.size());
    return block;
}
void draw_yado_text(const std::shared_ptr<::cw::lib::Surface>& surface,const YadoTextBlock& block,Integer x,Integer y) {
    for(const auto& line:block.lines) {
        if(line) ::cw::lib::ui::blend_surface(surface,line,x,y);
        y+=block.line_height;
    }
}
struct YadoLayout {
    ::cw::lib::Size size;
    ::cw::lib::Rect name,skin,autoload,preview,reference,ok,cancel;
    Integer input_height{},message_x{},message2_y{},label_x{};
    ::cw::lib::ui::FontStyle input_font,combo_font,check_font,label_font;
    YadoTextBlock message1,message2,name_label,skin_label,check_label;
};
// Python のサイザーの関係を最終ピクセル単位で表す。 文字の計測、入力
// 欄の当たり判定、ビットマップの配置では、追加の拡縮をせずこの配置を使う。
YadoLayout yado_layout(const YadoCreater& dialog) {
    namespace ui=::cw::lib::ui;
    namespace input=::cw::dialog::input_presentation;
    const auto px=[](Integer n){return ui::win_i(n);};
    YadoLayout out;
    out.label_font=ui::configured_wx_font("dlgmsg",16);
    out.input_font=ui::configured_wx_font("inputname",16);
    out.combo_font=ui::configured_wx_font("combo",16);
    out.check_font=ui::configured_wx_font("paneltitle2",15);
    const auto message_font=ui::configured_wx_font("dlgmsg2",16);
    out.message1=yado_text_block(value_string(dialog.m__msg1),out.label_font);
    out.message2=yado_text_block(::cw::util::txtwrap(value_string(dialog.m__msg2),0,32,{},false,nullptr),message_font);
    out.name_label=yado_text_block(message_or("input_name","宿の名前"),out.label_font);
    out.skin_label=yado_text_block(message_or("select_skin","スキン"),out.label_font);
    out.check_label=yado_text_block(message_or("autoload_party","パーティを自動選択"),out.check_font);
    const auto [cardw,cardh]=::cw::g_SIZE_CARDIMAGE;
    const Integer left=px(10+cardw),label_width=std::max(out.name_label.width,out.skin_label.width);
    const Integer name_height=px(24); // Python と同様、TextCtrl の寸法を 175×24 に固定する。
    const Integer skin_height=std::max(px(24),input::cell_height(out.combo_font)+px(8));
    const Integer check_height=std::max(px(18),out.check_label.height);
    const Integer column_width=std::max({std::max(out.message1.width,out.message2.width)+px(22),
        label_width+px(10+175+10),out.check_label.width+px(22+20)});
    out.message_x=px(cardw+20);
    // OnPaint2 は dlgmsg2 に切り替えてから、その前の行を計測する。
    out.message2_y=px(10)+yado_text_block(value_string(dialog.m__msg1),message_font).height+px(5);
    out.label_x=left+px(5);
    const Integer name_y=out.message1.height+out.message2.height+px(25);
    out.name={left+label_width+px(10),name_y,px(175),name_height};
    out.skin={out.name.x,name_y+name_height+px(5),px(150),skin_height};
    out.size.width=std::max(left+column_width,px(220));
    out.autoload={out.size.width-px(10)-out.check_label.width-px(22),out.skin.y+skin_height+px(10),
        out.check_label.width+px(22),check_height};
    out.input_height=std::max(out.autoload.y+check_height+px(10),px(cardh+30));
    out.preview={px(10),(out.input_height-px(cardh+30))/2,px(cardw),px(cardh)};
    out.reference={px(10+cardw-18),out.preview.y+px(cardh),px(18),px(30)};
    const Integer gap=(out.size.width-px(200))/3;
    out.ok={gap,out.input_height,px(100),px(30)};
    out.cancel={gap*2+px(100),out.input_height,px(100),px(30)};
    out.size.height=out.input_height+px(42);
    return out;
}
