bool yado_contains(const ::cw::lib::Rect& rect,float x,float y) {
    return std::isfinite(x) && std::isfinite(y) && x>=rect.x && x<rect.x+rect.width &&
        y>=rect.y && y<rect.y+rect.height;
}

