void AdventurerCreaterPage::set_imgpathlist(bool arg_reset)
{
    // Python のページ属性は一組だけだが、生成された C++ の NamePage
    // は AdventurerCreaterPage の互換フィールドに加
    // えて、 型付きの sex/age/imgdpath を持つ。画像検索で
    // は NamePage の型付きの値を読み、選択位置もそこへ書き戻す。
    const auto* name_page = dynamic_cast<const NamePage*>(this);
    const auto sex = name_page ? name_page->m_sex : m_sex;
    const auto age = name_page ? name_page->m_age : m_age;
    const auto drop_key = external_image_group_key();
    std::vector<std::vector<std::shared_ptr<::cw::image::ImageInfo>>> drop;
    if (const auto it = m_imgpathlist.find(drop_key); it != m_imgpathlist.end()) drop = it->second;
    if (arg_reset || m_imgpaths_typed.empty()) { m_imgpathlist.clear(); m_imgdpath = -1; }
    else { m_imgpathlist.clear(); m_imgpathlist[std::nullopt] = {m_imgpaths_typed}; m_imgdpath = 0; }
    if (!drop.empty()) m_imgpathlist[drop_key] = std::move(drop);
    const auto defaults = arg_reset || m_imgpaths_typed.empty();
    const auto face = ::cw::util::get_facepaths(sex, age, defaults);
    if (face.size() == 1 && drop.empty()) {
        if (const auto it = m_imgpathlist.find(std::nullopt); it != m_imgpathlist.end()) it->second.insert(it->second.end(), face.begin()->second.begin(), face.begin()->second.end());
        else m_imgpathlist[std::nullopt] = face.begin()->second;
    } else for (const auto& [key, paths] : face) m_imgpathlist[key] = paths;
    m_imgdpaths.clear();
    for (const auto& item : m_imgpathlist) m_imgdpaths.push_back(item.first);
    if (!m_imgpathlist.empty() && (arg_reset || m_imgpaths_typed.empty())) {
        auto it = m_imgpathlist.find(std::nullopt);
        if (it == m_imgpathlist.end()) it = m_imgpathlist.begin();
        if (!it->second.empty()) {
            m_imgpaths_typed = it->second.front();
            m_imgdpath = static_cast<Integer>(std::distance(m_imgdpaths.begin(), std::find(m_imgdpaths.begin(), m_imgdpaths.end(), it->first)));
        }
    }
    _update_imgdpaths();
    if (auto* typed_name_page = dynamic_cast<NamePage*>(this)) {
        typed_name_page->m_imgdpath = m_imgdpath;
        typed_name_page->m_imgpaths = m_imgpaths_typed;
    }
}

void AdventurerCreaterPage::_update_imgdpaths()
{
    if (m_imgdpaths.empty()) {
        m_imgdpath = -1;
    } else if (m_imgdpath < 0 || static_cast<std::size_t>(m_imgdpath) >= m_imgdpaths.size()) {
        m_imgdpath = 0;
    }
    if (m_ch_imgdpath) {
        // Windowのtitle/visibleはネイティブChoiceへ転送可能な状態キャッシュ。
        (*m_ch_imgdpath)->visible = m_imgdpaths.size() > 1;
        if (m_imgdpath >= 0) {
            const auto key = m_imgdpaths[static_cast<std::size_t>(m_imgdpath)];
            (*m_ch_imgdpath)->title = key ? std::get<1>(*key) : message_or("no_change", "<変更なし>");
        } else {
            (*m_ch_imgdpath)->title.clear();
        }
    }
}

