std::map<::cw::lib::String, ::cw::lib::String> AdventurerData::get_d()
{
    std::map<::cw::lib::String, ::cw::lib::String> d;
    const auto put_i = [&d](const char* n, auto v) {
        if constexpr (std::is_floating_point_v<decltype(v)>)
            d[n]=::cw::lib::PythonInteger::from_truncated_real(v).to_string();
        else d[n]=std::to_string(v);
    };
    const auto put_b = [&d](const char* n, bool v) { d[n] = v ? "True" : "False"; };
    d["id"]=m_id; d["name"]=m_name; d["description"]=m_description;
    put_i("level",m_level); put_i("maxlife",m_maxlife); put_i("life",m_life);
    put_b("undead",m_undead); put_b("automaton",m_automaton); put_b("unholy",m_unholy); put_b("constructure",m_constructure);
    put_b("noeffect_weapon",m_noeffect_weapon); put_b("noeffect_magic",m_noeffect_magic);
    put_b("resist_fire",m_resist_fire); put_b("resist_ice",m_resist_ice); put_b("weakness_fire",m_weakness_fire); put_b("weakness_ice",m_weakness_ice);
    put_i("dex",m_dex); put_i("agl",m_agl);
    put_i("int",m_py_int); put_i("str",m_str);
    put_i("vit",m_vit); put_i("min",m_min);
    put_i("aggressive",m_aggressive); put_i("cheerful",m_cheerful); put_i("brave",m_brave);
    put_i("cautious",m_cautious); put_i("trickish",m_trickish);
    put_i("avoid",m_avoid); put_i("resist",m_resist); put_i("defense",m_defense);
    put_b("has_parents",m_has_parents); put_i("maxdex",m_maxdex); put_i("maxagl",m_maxagl); put_i("maxint",m_maxint);
    put_i("maxstr",m_maxstr); put_i("maxvit",m_maxvit); put_i("maxmin",m_maxmin);
    d["indent"]=m_indent; d["mentality"]=m_mentality;
    put_i("duration_mentality",m_duration_mentality); put_i("paralyze",m_paralyze); put_i("poison",m_poison); put_i("bind",m_bind);
    put_i("silence",m_silence); put_i("faceup",m_faceup); put_i("antimagic",m_antimagic);
    put_i("duration_enhance_action",m_duration_enhance_action); put_i("enhance_action",m_enhance_action);
    put_i("duration_enhance_avoid",m_duration_enhance_avoid); put_i("enhance_avoid",m_enhance_avoid);
    put_i("duration_enhance_resist",m_duration_enhance_resist); put_i("enhance_resist",m_enhance_resist);
    put_i("duration_enhance_defense",m_duration_enhance_defense); put_i("enhance_defense",m_enhance_defense);
    d["items"]=m_items; d["skills"]=m_skills; d["beasts"]=m_beasts;
    if (m_coeff_ep) put_i("coeff_ep",*m_coeff_ep);
    if (m_coeff_level) put_i("coeff_level",*m_coeff_level);
    return d;
}

void AdventurerData::set_coupon(::cw::lib::String arg_name, ::cw::lib::Integer arg_value)
{
    const auto found = m_couponnames.find(arg_name);
    if (found == m_couponnames.end()) {
        m_couponnames[arg_name] = static_cast<::cw::lib::Integer>(m_coupons.size());
        m_coupons.emplace_back(std::move(arg_name), arg_value);
    } else if (arg_name == "＠レベル上限") {
        auto& coupon = m_coupons.at(static_cast<std::size_t>(found->second));
        if (std::get<1>(coupon) < arg_value) coupon = {arg_name, arg_value};
    }
}

