void AdventurerData::calc_level()
{
    m_level = 1;
    const auto found = m_couponnames.find("＠レベル上限");
    if (found == m_couponnames.end()) throw std::logic_error("＠レベル上限 coupon is required");
    const ::cw::lib::Integer limit = std::get<1>(m_coupons.at(static_cast<std::size_t>(found->second)));
    ::cw::lib::Integer total = 0;
    for (const auto& coupon : m_coupons) if (std::get<0>(coupon).rfind("＠", 0) != 0) total += std::get<1>(coupon);
    for (::cw::lib::Integer level = 1; level < limit; ++level) {
        if (!m_coeff_level) throw std::logic_error("coeff_level is not initialized");
        const auto required = static_cast<double>(level) * (static_cast<double>(level) + 1) * *m_coeff_level;
        if (!std::isfinite(required)) throw std::domain_error("level coefficient is not finite");
        if (std::trunc(required) <= static_cast<long double>(total)) m_level = level + 1;
        else break;
    }
}

void AdventurerData::set_race(std::shared_ptr<::cw::header::RaceHeader> arg_race)
{
    if (!arg_race) throw std::invalid_argument("race must not be null");
    m_undead |= arg_race->m_undead; m_automaton |= arg_race->m_automaton;
    m_unholy |= arg_race->m_unholy; m_constructure |= arg_race->m_constructure;
    m_noeffect_weapon |= arg_race->m_noeffect_weapon; m_noeffect_magic |= arg_race->m_noeffect_magic;
    m_resist_fire |= arg_race->m_resist_fire; m_resist_ice |= arg_race->m_resist_ice;
    m_weakness_fire |= arg_race->m_weakness_fire; m_weakness_ice |= arg_race->m_weakness_ice;
    m_dex += arg_race->m_dex; m_agl += arg_race->m_agl; m_py_int += arg_race->m_py_int;
    m_str += arg_race->m_str; m_vit += arg_race->m_vit; m_min += arg_race->m_min;
    m_aggressive += arg_race->m_aggressive; m_cheerful += arg_race->m_cheerful;
    m_brave += arg_race->m_brave; m_cautious += arg_race->m_cautious; m_trickish += arg_race->m_trickish;
    m_avoid += arg_race->m_avoid; m_resist += arg_race->m_resist; m_defense += arg_race->m_defense;
    m_maxdex = arg_race->m_dex + 6; m_maxagl = arg_race->m_agl + 6; m_maxint = arg_race->m_py_int + 6;
    m_maxstr = arg_race->m_str + 6; m_maxvit = arg_race->m_vit + 6; m_maxmin = arg_race->m_min + 6;
    m_coeff_level = arg_race->m_coeff_level.value_or(1.0);
    m_coeff_ep = arg_race->m_coeff_ep.value_or(10);
    if (!std::dynamic_pointer_cast<::cw::header::UnknownRaceHeader>(arg_race)) set_coupon("＠Ｒ" + arg_race->m_name, 0);
    for (const auto& [name, value] : arg_race->m_coupon_entries) set_coupon(name, value);
}

void AdventurerData::set_parents(std::optional<std::shared_ptr<::cw::header::AdventurerHeader>> arg_father, std::optional<std::shared_ptr<::cw::header::AdventurerHeader>> arg_mother)
{
    std::shared_ptr<::cw::header::Gene> father_gene;
    std::shared_ptr<::cw::header::Gene> mother_gene;
    if (arg_father && *arg_father) {
        m_has_parents = true;
        (*arg_father)->made_baby();
        if (!(*arg_father)->m_gene) throw std::logic_error("father gene is missing");
        father_gene = (*arg_father)->m_gene->rotate_father();
        auto coupon = message_or("father_coupon", "父親: %s");
        coupon = ::cw::lib::python_percent_string(coupon, (*arg_father)->m_name);
        set_coupon(std::move(coupon), 0);
    } else father_gene = random_gene();
    if (arg_mother && *arg_mother) {
        m_has_parents = true;
        if (!arg_father || *arg_father != *arg_mother) (*arg_mother)->made_baby();
        if (!(*arg_mother)->m_gene) throw std::logic_error("mother gene is missing");
        mother_gene = (*arg_mother)->m_gene->rotate_mother();
        auto coupon = message_or("mother_coupon", "母親: %s");
        coupon = ::cw::lib::python_percent_string(coupon, (*arg_mother)->m_name);
        set_coupon(std::move(coupon), 0);
    } else mother_gene = random_gene();
    m_gene = father_gene->fusion(mother_gene);
}

::cw::lib::String AdventurerData::set_gene(::cw::lib::String arg_talent)
{
    if (!m_gene) set_parents(std::nullopt, std::nullopt);
    const auto oldtalent = arg_talent;
    const auto count = m_gene && *m_gene ? (*m_gene)->count_bits() : 0;
    if (m_has_parents) {
        std::vector<std::shared_ptr<::cw::features::Nature>> special;
        for (const auto& nature : ::cw::setting::Setting::s_natures) if (nature && nature->m_special) special.push_back(nature);
        // Python と同様、安定ソートの後に reversed() を適用す
        // ることで、遺伝子数の閾値が等しい場合は後に設定された素質を優先する。
        std::stable_sort(special.begin(), special.end(), [](const auto& lhs, const auto& rhs) { return lhs->m_genecount < rhs->m_genecount; });
        for (auto it = special.rbegin(); it != special.rend(); ++it) {
            const auto& nature = *it;
            if (nature->m_genecount == 0) {
                if (count == 0) { arg_talent = "＿" + nature->m_name; break; }
            } else {
                const auto candidate = arg_talent.size() > 2 ? arg_talent.substr(3) : arg_talent;
                if (count >= nature->m_genecount &&
                    (nature->m_basenatures.empty() ||
                     std::find(nature->m_basenatures.begin(), nature->m_basenatures.end(), candidate) != nature->m_basenatures.end())) {
                    arg_talent = "＿" + nature->m_name;
                    if (m_gene && *m_gene) m_gene = (*m_gene)->reverse();
                    break;
                }
            }
        }
    }
    for (const auto& nature : ::cw::setting::Setting::s_natures) if (nature && "＿" + nature->m_name == arg_talent) {
        modulate_feature(*this, *nature);
        set_coupon("＠レベル上限", nature->m_levelmax);
        break;
    }
    if (m_gene && *m_gene) { (*m_gene)->set_talentbit(arg_talent, oldtalent); set_coupon("＠Ｇ" + (*m_gene)->get_str(), 0); }
    return arg_talent;
}

