void DesignPanel::initialize(std::shared_ptr<::cw::dialog::create::AdventurerDesignDialog> arg_parent, std::shared_ptr<::cw::character::Player> arg_ccard)
{
    (void)arg_parent;
    m_ccard = arg_ccard ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(arg_ccard)) : ::cw::lib::Value{};
    m_imgpaths.clear();
    m_oldimgpath.clear();
    m_image_access.clear();
    m_can_loaded_scaledimage=false;
    if (!arg_ccard) return;
    if(const auto* object=std::get_if<::cw::lib::ObjectPtr>(&arg_ccard->m_data.storage());object && *object) {
        const auto tree=std::dynamic_pointer_cast<::cw::data::CWPyElementTree>(*object);
        if(tree && tree->getroot()) m_can_loaded_scaledimage=tree->getroot()->getbool(".",::cw::lib::Value("scaledimage"),false);
    }

    m_name = arg_ccard->get_name();
    m_desc = arg_ccard->get_description();
    m_sex = arg_ccard->get_sex();
    m_age = arg_ccard->get_age();
    m_centering = true;
    for (const auto& source : arg_ccard->get_imagepaths()) {
        if (!source) continue;
        if (source->m_postype != "Center") m_centering = false;
        auto info = std::make_shared<::cw::image::ImageInfo>();
        info->initialize(::cw::util::join_yadodir(source->m_path), source->m_pcnumber, source, source->m_postype, String("LargeCard"));
        // oldimgpathはOnCentering/画像選択で現在値を書き換えても比較元を保つ。
        m_oldimgpath.push_back(info->copy());
        m_imgpaths.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
    }
    // 現在の画像は None の下に保持する。Python の絞り込み付き選択画面とは異なり、
    // 手動編集では名前の付いたすべての Face フォルダーを個別の選択肢として公開する。
    m_imgpathlist_typed.clear();
    m_imgdpaths_typed.clear();
    m_imgpaths_current_typed.clear();
    for (const auto& value : m_imgpaths) {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
        if (object && *object) if (const auto info = std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object)) m_imgpaths_current_typed.push_back(info);
    }
    if (!m_imgpaths_current_typed.empty()) m_imgpathlist_typed[std::nullopt].push_back(m_imgpaths_current_typed);
    const auto facepaths = ::cw::util::get_facepaths(value_string(m_sex), value_string(m_age), false, true);
    // 名前の付いたフォルダーが一つだけでも「変更しない」とは分ける。
    // 既存画像に紛れてフォルダーを手動選択できなくならないようにする。
    for (const auto& [key, paths] : facepaths) m_imgpathlist_typed[key] = paths;
    for (const auto& [key, unused] : m_imgpathlist_typed) { (void)unused; m_imgdpaths_typed.push_back(key); }
    if (!m_imgdpaths_typed.empty()) {
        auto it = std::find(m_imgdpaths_typed.begin(), m_imgdpaths_typed.end(), std::nullopt);
        if (it == m_imgdpaths_typed.end()) it = m_imgdpaths_typed.begin();
        m_imgdpath = static_cast<Integer>(std::distance(m_imgdpaths_typed.begin(), it));
        const auto group = m_imgpathlist_typed.find(*it);
        if (group != m_imgpathlist_typed.end() && !group->second.empty()) m_imgpaths_current_typed = group->second.front();
    }
    m_imgpaths.clear();
    for (const auto& info : m_imgpaths_current_typed) if (info) m_imgpaths.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
    m_centering_shown = image_requires_centering(m_imgpaths_current_typed);
}

