bool DesignPanel::is_changedimgpath()
{
    std::vector<std::shared_ptr<::cw::image::ImageInfo>> paths;
    paths.reserve(m_imgpaths.size());
    for (const auto& value : m_imgpaths) {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
        paths.push_back(object && *object
            ? std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object) : nullptr);
    }
    return !same_imagepaths(paths, m_oldimgpath);
}

std::vector<std::shared_ptr<::cw::image::ImageInfo>> DesignPanel::selected_imagepaths() const
{
    std::vector<std::shared_ptr<::cw::image::ImageInfo>> result;
    for(const auto& value:m_imgpaths) {
        const auto* object=std::get_if<::cw::lib::ObjectPtr>(&value.storage());
        const auto source=object && *object?std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object):nullptr;
        if(!source) continue;
        auto info=source->copy();
        if(m_centering_shown) {
            if(m_centering) info->m_postype="Center";
            else if(info->m_postype=="Center") info->m_postype="Default";
        }
        result.push_back(std::move(info));
    }
    return result;
}

