void DesignPanel::OnChoiceImgDPath(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(!arg_event) return;
    Integer choice;
    try {std::size_t used=0;choice=std::stoll(arg_event->title,&used);if(used!=arg_event->title.size()) return;}
    catch(...) {return;}
    if(choice<0 || static_cast<std::size_t>(choice)>=m_imgdpaths_typed.size() || choice==value_integer(m_imgdpath)) return;
    create_play_sound("page");m_imgdpath=choice;
    _choice_imgdpath();
}

void DesignPanel::_choice_imgdpath()
{
    const auto index = value_integer(m_imgdpath, 0);
    if (index < 0 || static_cast<std::size_t>(index) >= m_imgdpaths_typed.size()) return;
    const auto it = m_imgpathlist_typed.find(m_imgdpaths_typed[static_cast<std::size_t>(index)]);
    if (it == m_imgpathlist_typed.end() || it->second.empty()) return;
    m_imgpaths_current_typed = it->second.front();
    m_imgpaths.clear();
    for (const auto& info : m_imgpaths_current_typed) if (info) m_imgpaths.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
    m_imgdpath = index;
    m_centering_shown = image_requires_centering(m_imgpaths_current_typed);
}

bool DesignPanel::put_image_files(const std::vector<String>& paths)
{
    // Python の AdventurerCreaterPage._put_image と同様、各ファイルは重ねるレイヤーではなく、切り替える画像候補とする。
    std::vector<std::vector<std::shared_ptr<::cw::image::ImageInfo>>> candidates;
    for(const auto& path:paths) {
        if(path.empty() || path.find('\0')!=String::npos) continue;
        auto ext=std::get<1>(::cw::util::splitext(path));
        std::transform(ext.begin(),ext.end(),ext.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});
        bool supported=false;
        std::apply([&](const auto&... value){((supported=supported || ext==value),...);},::cw::g_EXTS_IMG);
        if(supported) candidates.push_back(path_to_imageinfo(::cw::util::find_noscalepath(path)));
    }
    if(candidates.empty()) {create_play_sound("error");return false;}
    const auto key = std::make_optional(external_image_group_key());
    auto groups=m_imgdpaths_typed;
    groups.erase(std::remove(groups.begin(),groups.end(),key),groups.end());
    const auto unchanged=std::find(groups.begin(),groups.end(),std::nullopt);
    const auto index=unchanged==groups.end()?0:static_cast<std::size_t>(std::distance(groups.begin(),unchanged))+1;
    groups.insert(groups.begin()+index,key);
    m_imgpathlist_typed[key]=std::move(candidates);
    m_imgdpaths_typed=std::move(groups);
    m_imgdpath=static_cast<Integer>(index);
    _choice_imgdpath();
    create_play_sound("equipment");
    return true;
}

bool AdventurerDesignDialog::choose_image_files(const std::function<std::vector<String>()>& choose)
{
    // 互換用・テスト用の注入に限る。更新はすべて同じ非同期結果の経路
    // で処理し、 通常の参照ボタンから入れ子の待機ループへ入らない。
    if(!choose) return false;
    using namespace ::cw::lib::documents;
    const bool started=request_image_files([&](const Request& req,Completion complete) {
        return request(req,[](std::function<void()> work){work();return true;},std::move(complete),
            [&](const Request&,Completion done,Cancelled) {
                const auto paths=choose();
                Result result{paths.empty()?Status::Cancelled:Status::Success,{},{}};
                for(const auto& path:paths) result.documents.push_back({LocationKind::NativePath,path,{}});
                done(std::move(result));
            });
    });
    return started && m_image_last_changed;
}

bool AdventurerDesignDialog::request_image_files(ImageRequest start)
{
    using namespace ::cw::lib::documents;
    if(design_input_blocked() || !visible || !m_toppanel || weak_from_this().expired()) return false;
    sync_text_edits();
    if(design_composing()) return false;
    if(!start) start=::cw::dialog::request_presentation_document;
    const auto panel=m_toppanel;const auto token=std::make_shared<int>(0);
    m_image_request_token=token;m_image_last_changed=false;m_text_drag=-1;
    request_dialog_presentation_refresh();
    Request request;
    request.title=message_or("select_signboard","画像ファイルの選択");request.multiple=true;
    request.transient_read_limit=transient_image_import_limit;
    request.filters={{"画像ファイル","jpg;jpeg;png;gif;bmp;tiff;xpm"},{"すべてのファイル","*"}};
    const auto weak=weak_from_this();
    try {
        auto ticket=start(request,[weak,token,panel](Result result) {
            if(const auto owner=weak.lock()) owner->finish_image_request(token,panel,std::move(result));
        });
        if(m_image_request_token==token) {
            m_image_ticket=std::move(ticket);
            if(!m_image_ticket || !m_image_ticket->pending())
                finish_image_request(token,panel,{Status::Failed,{},"ファイル選択を開始できませんでした"});
        }
    } catch(const std::exception& e) {finish_image_request(token,panel,{Status::Failed,{},e.what()});}
      catch(...) {finish_image_request(token,panel,{Status::Failed,{},"ファイル選択を開始できませんでした"});}
    return true;
}

void AdventurerDesignDialog::finish_image_request(const std::shared_ptr<int>& token,
    const std::shared_ptr<DesignPanel>& panel,::cw::lib::documents::Result result)
{
    using namespace ::cw::lib::documents;
    if(m_image_request_token!=token) return;
    struct Release {
        AdventurerDesignDialog& owner;std::shared_ptr<int> token;
        ~Release(){if(owner.m_image_request_token==token){
            owner.m_image_request_token.reset();owner.m_image_ticket.reset();owner.request_dialog_presentation_refresh();
        }}
    } release{*this,token};
    if(m_toppanel!=panel || m_presentation_finished || !visible) return;
    if(result.status==Status::Cancelled) return;
    try {
        if(result.status==Status::Success) {
            std::vector<String> paths;std::vector<std::shared_ptr<void>> access;
            for(const auto& document:result.documents) {
                if(document.kind!=LocationKind::NativePath) {
                    result={Status::Unsupported,{},"画像取得サービスがプロバイダーURIをローカル画像へ変換しませんでした"};break;
                }
                paths.push_back(document.location);if(document.access) access.push_back(document.access);
            }
            if(result.status==Status::Success && !paths.empty()) {
                m_image_last_changed=panel->put_image_files(paths);
                if(m_image_last_changed) {panel->m_image_access=std::move(access);m_presentation_group_open=false;}
                return;
            }
        }
    } catch(const std::exception& e) {result.error=e.what();}
      catch(...) {result.error="画像の取得に失敗しました";}
    if(result.error.empty()) result.error="ファイル選択に失敗しました";
    create_play_sound("error");
    (void)::cw::dialog::message::show_common_modal_message("画像の選択",result.error,false,true);
}

void AdventurerDesignDialog::dialog_presentation_drop_files(const std::vector<std::string>& paths)
{
    if(design_input_blocked() || !visible || !m_toppanel || paths.empty()) return;
    sync_text_edits();
    if(design_composing()) return;
    // パスを区切り文字付きの Window タイトルに埋め込まない。セミコロンや改行もファイル名に含まれ得る。
    if(m_toppanel->put_image_files(paths)) {
        m_toppanel->m_image_access.clear();
        m_presentation_group_open=false;m_text_drag=-1;
        request_dialog_presentation_refresh();
    }
}

