void DesignPanel::set_nextimg(::cw::lib::String arg_name)
{
    (void)arg_name;
    auto group_index = value_integer(m_imgdpath, 0);
    try {
        step_creator_image(group_index, m_imgdpaths_typed, m_imgpathlist_typed,
                           m_imgpaths_current_typed, m_ch_imgdpath, true);
    } catch (...) {
        // Py と同様、画像の取得に失敗する場合も、検索より先にグループを更新する。
        m_imgdpath = group_index;
        throw;
    }
    m_imgdpath = group_index;
    m_imgpaths.clear();
    for (const auto& info : m_imgpaths_current_typed)
        if (info) m_imgpaths.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
    m_centering_shown = image_requires_centering(m_imgpaths_current_typed);
}

