void NamePage::_up_imgd()
{
    if (m_imgdpaths.size() <= 1) return; // Python と同様、一グループだけで非表示になっている Choice は無視する。
    const auto count = static_cast<Integer>(m_imgdpaths.size());
    const auto selected = std::clamp<Integer>(m_imgdpath, 0, count - 1);
    auto event = std::make_shared<::cw::lib::Window>();
    event->title = std::to_string((selected + count - 1) % count);
    OnChoiceImgDPath(event);
}

