void NamePage::select_autofeatures()
{
    if (::cw::setting::Setting::s_sexcoupons.empty()) throw std::out_of_range("sex list is empty");
    m_sex = ::cw::setting::Setting::s_sexcoupons[static_cast<std::size_t>(dice_roll(static_cast<Integer>(::cw::setting::Setting::s_sexcoupons.size())) - 1)];
    m_age = ::cw::setting::Setting::s_periodcoupons[::cw::dice::choice_index(::cw::setting::Setting::s_periodcoupons.size())];
    if (m_input_name.empty()) {
        const auto it = std::find(::cw::setting::Setting::s_sexcoupons.begin(), ::cw::setting::Setting::s_sexcoupons.end(), m_sex);
        if (it != ::cw::setting::Setting::s_sexcoupons.end()) {
            const auto index = static_cast<std::size_t>(std::distance(::cw::setting::Setting::s_sexcoupons.begin(), it));
            const auto name=get_randomname(index < ::cw::setting::Setting::s_sexsubnames.size()
                                         ? ::cw::setting::Setting::s_sexsubnames[index] : String{});
            if(!name.empty())m_name=name;
        }
    }
    set_imgpathlist(true);
    if (!m_imgdpaths.empty()) {
        m_imgdpath = dice_roll(static_cast<Integer>(m_imgdpaths.size())) - 1;
        _choice_imgdpath();
        if (m_imgdpath >= 0 && static_cast<std::size_t>(m_imgdpath) < m_imgdpaths.size()) {
            const auto it = m_imgpathlist.find(m_imgdpaths[static_cast<std::size_t>(m_imgdpath)]);
            if (it != m_imgpathlist.end() && !it->second.empty()) {
                m_imgpaths_typed = it->second[static_cast<std::size_t>(
                    ::cw::dice::choice_index(it->second.size()))];
                m_imgpaths = m_imgpaths_typed;
            }
        }
    } else {
        m_imgpaths = m_imgpaths_typed;
    }
    m_centering_shown = image_requires_centering(m_imgpaths);
    if (const auto creator=m_creator.lock()) creator->enable_btn();
    draw(true);
}

