void RelationPage::set_parents()
{
    if(::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata) {
        const auto yado=*::cw::g_cwpy->m_ydata;
        set_parents_from_headers(yado->m_standbys,yado->m_album);
    } else set_parents_from_headers({},{});
}

void RelationPage::set_parents_from_headers(
    const std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>& standbys,
    const std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>& album)
{
    m_fathers={std::nullopt};m_mothers={std::nullopt};
    for(const auto* collection:{&standbys,&album})for(const auto& header:*collection) {
        if(!header)continue;
        for(const auto& period : ::cw::setting::Setting::s_periods) {
            if(!period || period->m_spendep<=0 || value_string(header->m_age)!="＿"+period->m_name)continue;
            const auto cost=header->m_album?period->m_spendep/2:period->m_spendep;
            if(header->m_ep<cost)continue;
            for(const auto& sex : ::cw::setting::Setting::s_sexes)
                if(sex && value_string(header->m_sex)=="＿"+sex->m_name) {
                    if(sex->m_father)m_fathers.emplace_back(header);
                    if(sex->m_mother)m_mothers.emplace_back(header);
                    break;
                }
            break;
        }
    }
}

bool RelationPage::is_skip()
{
    return m_fathers.size() <= 1 && m_mothers.size() <= 1;
}

void RelationPage::select_autofeatures()
{
    create_play_sound("signal");
    // cw.dice.choice は choice_exists と異なり、空のリストに対して None を返す。
    if (m_fathers.empty()) m_father.reset();
    else m_father = m_fathers[::cw::dice::choice_index(m_fathers.size())];
    if (m_mothers.empty()) m_mother.reset();
    else m_mother = m_mothers[::cw::dice::choice_index(m_mothers.size())];
    draw(true);
}

