void YadoCreater::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, std::optional<::cw::lib::String> arg_yadodir)
{
    dialog_retained_surface().reset();
    m_image_request_token.reset();m_image_ticket.reset();m_signboard_access.reset();m_image_error.clear();
    m_save_pending=false;m_save_error.clear();m_initial_skindirname.reset();
    m_skin_popup=false;m_skin_cursor=m_skin_offset=0;m_skin_search.reset();m_skin_hover_controls.clear();
    native_handle = arg_parent ? arg_parent->native_handle : 0;
    parent_window = arg_parent;
    visible = true;
    m_modal_closed = false;
    m_modal_result_ok = false;
    m_presentation_finished = false;
    if (::cw::g_fsync) ::cw::g_fsync->sync();
    m_create = !arg_yadodir.has_value();
    m_yadodir = arg_yadodir;
    m_data_typed.reset();
    m_imgpaths_typed.clear();
    m_imgpaths_init_typed.clear();
    m_skindirnames_typed.clear();
    m_skindirnames.clear();
    m_skinlabels_typed.clear();
    m_command0paths_typed.clear();
    m_cautionpaths_typed.clear();
    m_name.clear();
    m_skindirname = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::g_cwpy->m_setting->m_skindirname : String{};
    m_is_autoloadparty_typed = true;

    if (m_create) {
        m_name = message_or("new_base", "新しい宿");
        m__msg1 = ::cw::lib::Value(message_or("create_base_message_1", "宿を作成します。"));
        m__msg2 = ::cw::lib::Value(message_or("create_base_message_2", "宿の名前とスキンを選択してください。"));
    } else if (m_yadodir && !m_yadodir->empty()) {
        {
            const auto env = std::filesystem::u8path(*m_yadodir) / "Environment.xml";
            m_data_typed = ::cw::data::yadoxml2etree(::cw::lib::encoding::path_to_utf8(env), "", std::nullopt);
            if (m_data_typed) {
                m_name = m_data_typed->gettext("Property/Name", "");
                m_skindirname = m_data_typed->gettext("Property/Skin",
                                                       (::cw::g_cwpy && ::cw::g_cwpy->m_setting)
                                                           ? ::cw::g_cwpy->m_setting->m_skindirname : "");
                m_is_autoloadparty_typed = m_data_typed->getbool("Property/NowSelectingParty", ::cw::lib::Value("autoload"), true);
                const auto property = m_data_typed->find_exists("Property");
                if (property) {
                    m_imgpaths_typed = ::cw::image::get_imageinfos(property, false);
                    for (const auto& info : m_imgpaths_typed) if (info && !info->m_path.empty())
                        info->m_path=::cw::util::join_paths({*m_yadodir,info->m_path});
                }
            }
        }
        m__msg1 = ::cw::lib::Value(message_or("edit_base_message_1", "宿を編集します。"));
        m__msg2 = ::cw::lib::Value(message_or("edit_base_message_2", "宿の設定を編集してください。"));
    }
    m_initial_skindirname=m_skindirname;
    for (const auto& info : m_imgpaths_typed) m_imgpaths_init_typed.push_back(info ? info->copy() : nullptr);
    m_imgpaths = ::cw::lib::Value(static_cast<::cw::lib::Integer>(m_imgpaths_typed.size()));
    m_imgpaths_init = ::cw::lib::Value(static_cast<::cw::lib::Integer>(m_imgpaths_init_typed.size()));
    m_textctrl = ::cw::lib::Value(m_name);
    m_name_menu.close();m_name_modifiers=0;
    m_name_edit.reset(m_name,false,false);m_input_focus=0;m_name_dragging=false;
    m_is_autoloadparty = m_is_autoloadparty_typed;

    // Skin.xmlのTypeが編集中宿のTypeと一致するものだけをPython版と同じ順序で列挙する。
    String skintype;
    if (!m_create) {
        const auto skinxml=std::filesystem::u8path("Data/Skin")/std::filesystem::u8path(m_skindirname)/"Skin.xml";
        if (std::filesystem::is_regular_file(skinxml)) {
            auto prop=std::make_shared<::cw::header::GetProperty>();
            prop->initialize(::cw::lib::encoding::path_to_utf8(skinxml),std::nullopt,std::nullopt);
            skintype=prop->m_properties["Type"];
        } else if (m_data_typed) skintype=m_data_typed->gettext("Property/Type","");
    }
    {
        for (const auto& entry : std::filesystem::directory_iterator("Data/Skin")) {
            if (!entry.is_directory()) continue;
            const auto skinxml = entry.path() / "Skin.xml";
            if (!std::filesystem::is_regular_file(skinxml)) continue;
            try {
                auto prop = std::make_shared<::cw::header::GetProperty>();
                prop->initialize(::cw::lib::encoding::path_to_utf8(skinxml), std::nullopt, std::nullopt);
                if (!skintype.empty() && prop->m_properties["Type"] != skintype) continue;
                const auto dirname = ::cw::lib::encoding::path_to_utf8(entry.path().filename());
                const auto label = prop->m_properties.at("Name");
                m_skindirnames_typed.push_back(dirname);
                m_skinlabels_typed.push_back(label);
                m_skindirnames.emplace_back(dirname);
                const auto skinroot = entry.path();
                m_command0paths_typed.push_back(::cw::util::find_resource(::cw::lib::encoding::path_to_utf8(skinroot / "Resource/Image/Card/COMMAND0"), ::cw::g_M_IMG));
                m_cautionpaths_typed.push_back(::cw::util::find_resource(::cw::lib::encoding::path_to_utf8(skinroot / "Resource/Image/Dialog/CAUTION"), ::cw::g_M_IMG));
            } catch (...) {
                // Python版と同じく、読めないスキン1件だけを候補から除外する。
                ::cw::util::print_ex(std::nullopt);
            }
        }
    }
    if (std::find(m_skindirnames_typed.begin(), m_skindirnames_typed.end(), m_skindirname) == m_skindirnames_typed.end() &&
        !m_skindirnames_typed.empty()) {
        const auto preferred = ::cw::g_cwpy && ::cw::g_cwpy->m_setting
                                   ? ::cw::g_cwpy->m_setting->m_skindirname : String{};
        const auto preferred_it = std::find(m_skindirnames_typed.begin(), m_skindirnames_typed.end(), preferred);
        m_skindirname = preferred_it == m_skindirnames_typed.end()
                            ? m_skindirnames_typed.front() : *preferred_it;
    }
    m_skin = ::cw::lib::Value(m_skindirname);
    _bind();
    _do_layout();
}

namespace {
// これらのロックは既存の共通ミューテックスを使い、同期的に取得して逆順に解放する
// 。 両方の保護が解除されるまで、入れ子のダイアログやコールバックを実行しない。
String yado_edit_name(const ::cw::lib::Value& value,const String& fallback) {
    return ::cw::lib::python_strip(value_string(value,fallback));
}

}

void YadoCreater::create_yado()
{
    auto name=yado_edit_name(m_textctrl,m_name);
    if(name.empty()) throw std::invalid_argument("宿の名前を入力してください");
    auto skin=value_string(m_skin,m_skindirname);
    const auto filename=::cw::binary::util::check_filename(name);
    if(filename.empty() || filename=="." || filename=="..")
        throw std::invalid_argument("保存できる宿の名前を入力してください");
    auto yado_root=std::filesystem::u8path("Yado");
    if(const auto mounted=::cardwirth::platform::resolve_mounted_user_path(yado_root))
        yado_root=*mounted;
    const auto path=::cw::binary::util::check_duplicate(::cw::lib::encoding::path_to_utf8(
        yado_root/std::filesystem::u8path(filename)));
    m_yadodir=path;
    const auto owned=std::filesystem::u8path(path).lexically_normal();
    const bool mounted=::cardwirth::platform::is_mounted_user_path(owned);
    const bool created=mounted
        ? ::cardwirth::platform::reserve_mounted_user_directory(owned)
        : std::filesystem::create_directories(owned);
    if(!created)
        throw std::runtime_error("宿の保存先が既に存在します: "+path);
    for(const auto& dir:{"Adventurer","Album","BeastCard","ItemCard","Material","Party","SkillCard"}) {
        const auto child=owned/dir;
        if(mounted) {
            if (!::cardwirth::platform::make_mounted_user_directory(child,false))
                throw std::runtime_error("宿のサブフォルダを作成できません: "+::cw::lib::encoding::path_to_utf8(child));
        } else std::filesystem::create_directory(child);
    }
    ::cw::xmlcreater::create_environment(name,path,skin,m_is_autoloadparty,m_imgpaths_typed);
}


void YadoCreater::edit_yado()
{
    if (!::cw::util::create_mutex("Yado")) { create_play_sound("error"); return; }
    ::cw::lib::finally_call([&] {
        if (!m_yadodir || m_yadodir->empty()) throw std::logic_error("Editing requires an inn");
        if (!::cw::util::create_mutex(*m_yadodir)) { create_play_sound("error"); return; }
        ::cw::lib::finally_call([&] {
            create_play_sound("harvest");
            _edit_yado_impl();
            ::cw::util::rename_file(*m_yadodir+"/Environment.xml",*m_yadodir+"/Environment.xml.tmp",false);
        },[] { ::cw::util::release_mutex(); });
        _move_dir(m_name);
        ::cw::util::rename_file(*m_yadodir+"/Environment.xml.tmp",*m_yadodir+"/Environment.xml",false);
        m_modal_result_ok=true;m_modal_closed=true;m_presentation_finished=true;visible=false;
    },[] { ::cw::util::release_mutex(); });
}

void YadoCreater::write_yado_environment(const std::shared_ptr<::cw::data::CWPyElementTree>& tree)
{
    if(!tree) throw std::invalid_argument("write_yado_environment: null tree");
    auto path=std::filesystem::u8path(tree->m_fpath);
    if(!::cardwirth::platform::is_mounted_user_path(path))
        path=std::filesystem::absolute(path);
    tree->write_file(::cw::lib::encoding::path_to_utf8(path));
    // sync() は予約済みの書き込みを待ち、最初の書き込み失敗を再送出する。
    // この書き込み完了待ちの時点では、Py の実体のツリーは既に編集済みである。
    if (::cw::g_fsync) ::cw::g_fsync->sync();
}

void YadoCreater::_edit_yado_impl()
{
    if(!m_yadodir || m_yadodir->empty()) throw std::runtime_error("編集する宿がありません");
    auto name=yado_edit_name(m_textctrl,m_name);
    if(name.empty()) throw std::invalid_argument("宿の名前を入力してください");
    auto skin=value_string(m_skin,m_skindirname);
    const bool autoload=m_is_autoloadparty;
    const bool images_changed=m_imgpaths_typed.size()!=m_imgpaths_init_typed.size() || [&] {
        for(std::size_t i=0;i<m_imgpaths_typed.size();++i) {
            const auto& a=m_imgpaths_typed[i];const auto& b=m_imgpaths_init_typed[i];
            if(bool(a)!=bool(b) || (a && (a->m_path!=b->m_path || a->m_pcnumber!=b->m_pcnumber || a->m_postype!=b->m_postype))) return true;
        }
        return false;
    }();
    auto source=m_data_typed;
    if(!source) source=::cw::data::yadoxml2etree(::cw::lib::encoding::path_to_utf8(
        std::filesystem::u8path(*m_yadodir)/"Environment.xml"),"",std::nullopt);
    if(!source || !source->getroot()) throw std::runtime_error("宿の設定を読み込めませんでした");
    // Python は書き込み失敗で self.data が変わった後も、元の self.skindirname
    // と比較する。 ネイティブの m_skindirname はプレビューに
    // も使うため、元の値を UI と実体の XML の両方から分けて保持する。
    if(!m_initial_skindirname) m_initial_skindirname=source->gettext("Property/Skin",m_skindirname);
    if(name==m_name && skin==*m_initial_skindirname &&
       autoload==m_is_autoloadparty_typed && !images_changed) return;
    auto tree=source;
    m_data_typed=tree;
    auto property=tree->find_exists("Property");
    if(auto old=property->find("Name")) (*old)->set_text(name);
    else property->insert(0,::cw::data::make_element("Name",name));
    tree->edit("Property/Skin",skin,std::nullopt);
    tree->edit("Property/NowSelectingParty",autoload?"True":"False",std::optional<String>("autoload"));
    if (images_changed) {
        if(auto old=property->find("ImagePath")) property->remove(*old);
        const auto paths=property->find("ImagePaths");
        const auto image_root=paths ? *paths : ::cw::data::make_element("ImagePaths");
        if(!paths) property->append(image_root);
        image_root->clear();
        ::cw::xmlcreater::copy_yadoimgpaths(*m_yadodir,m_imgpaths_typed);
        for (const auto& old:m_imgpaths_init_typed) if (old && ::cw::util::path_is_file(old->m_path))
            ::cw::util::remove_scaledimagepaths(old->m_path,true,false);
        for (const auto& info:m_imgpaths_typed) if(info && !info->m_path.empty()) {
            auto e=::cw::data::make_element("ImagePath",info->m_path);info->set_attr(e);image_root->append(e);
        }
        ::cw::util::remove_emptydir(*m_yadodir+"/Material/Signboard");
    }
    tree->m_is_edited=true;
    write_yado_environment(tree);
}

void YadoCreater::_move_dir(std::optional<String> previous_name)
{
    if (!m_yadodir) throw std::logic_error("Moving requires an inn");
    const auto name=yado_edit_name(m_textctrl,m_name);
    const auto oldpath = std::filesystem::u8path(*m_yadodir);
    const auto oldname = ::cw::lib::encoding::path_to_utf8(oldpath.filename());
    if(oldname.empty() || oldname=="." || oldname=="..") return;
    try {
        // Python と同様、スキンだけを編集した場合も、この宿のローカルキャッシュを消去
        // する。 このメソッドは保存成功後だけに実行し、キャッシュのルートは対象にしない。
        auto cache=std::filesystem::u8path("Data/Temp/Local")/std::filesystem::u8path(oldname);
        if(const auto mounted=::cardwirth::platform::resolve_mounted_user_path(cache)) cache=*mounted;
        ::cw::util::remove(::cw::lib::encoding::path_to_utf8(cache), false);
        if(name==previous_name.value_or(m_name)) return;
        const auto wanted=::cw::binary::util::check_filename(name);
        if(wanted.empty() || wanted=="." || wanted==".." || wanted==oldname) return;
        const auto candidate=oldpath.parent_path()/std::filesystem::u8path(wanted);
        // ファイルシステム上のオブジェクトの同一性ではなく、Py と同じ正規化後の表記を比較する。
        if (::cw::util::get_keypath(oldname)==::cw::util::get_keypath(wanted)) return;
        auto newpath=::cw::binary::util::check_duplicate(::cw::lib::encoding::path_to_utf8(candidate));
        const auto new_native=std::filesystem::u8path(newpath);
        if(::cardwirth::platform::is_mounted_user_path(oldpath)) {
            if(!::cardwirth::platform::rename_mounted_user_path(oldpath,new_native,false))
                throw std::runtime_error("宿フォルダの名前を変更できませんでした");
        } else std::filesystem::rename(oldpath,new_native);
        m_yadodir = newpath;
        if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
            auto& setting = *::cw::g_cwpy->m_setting;
            if (setting.m_lastyado == oldname) setting.m_lastyado = ::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(newpath).filename());
            const auto it = setting.m_yado_order.find(oldname);
            if (it != setting.m_yado_order.end()) { const auto order = it->second; setting.m_yado_order.erase(it); setting.m_yado_order[::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(newpath).filename())] = order; }
        }
    } catch (...) {
        ::cw::util::print_ex(std::nullopt);
    }
}

void YadoCreater::_put_image(::cw::lib::String arg_fpath)
{
    if(m_presentation_finished || image_request_pending() || m_save_pending || m_skin_popup || !visible) return;
    (void)set_signboard(arg_fpath);
}

bool YadoCreater::set_signboard(const String& arg_fpath,std::shared_ptr<void> access)
{
    if (arg_fpath.empty() || arg_fpath.find('\0')!=String::npos) return false;
    if(yado_composing()) return false;
    auto ext = std::get<1>(::cw::util::splitext(arg_fpath));
    std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    bool image = false;
    std::apply([&](const auto&... value) { ((image = image || ext == value), ...); }, ::cw::g_EXTS_IMG);
    if (!image) {
        create_play_sound("error");
        return false;
    }
    create_play_sound("equipment");
    auto info = std::make_shared<::cw::image::ImageInfo>();
    info->initialize(::cw::util::find_noscalepath(arg_fpath), 0, std::nullopt, "TopLeft", std::nullopt);
    m_imgpaths_typed = {std::move(info)};
    m_imgpaths=Integer{1};m_signboard_access=std::move(access);
    request_dialog_presentation_refresh();return true;
}

bool YadoCreater::request_signboard(ImageRequest start)
{
    using namespace ::cw::lib::documents;
    if(m_presentation_finished || !visible || image_request_pending() || m_save_pending || m_skin_popup || weak_from_this().expired()) return false;
    if(yado_composing()) return false;
    if(!start) start=::cw::dialog::request_presentation_document;
    const auto token=std::make_shared<int>(0);m_image_request_token=token;m_image_error.clear();
    request_dialog_presentation_refresh();
    Request request;request.title=message_or("select_signboard","看板画像の選択");request.multiple=false;
    request.transient_read_limit=transient_image_import_limit;
    request.filters={{"画像ファイル","jpg;jpeg;png;gif;bmp;tif;tiff;xpm"},{"すべてのファイル","*"}};
    const auto weak=weak_from_this();
    try {
        auto ticket=start(request,[weak,token](Result result) {
            if(const auto owner=weak.lock()) owner->finish_signboard_request(token,std::move(result));
        });
        if(m_image_request_token==token) {
            m_image_ticket=std::move(ticket);
            if(!m_image_ticket || !m_image_ticket->pending())
                finish_signboard_request(token,{Status::Failed,{},"ファイル選択を開始できませんでした"});
        }
    } catch(const std::exception& e) {finish_signboard_request(token,{Status::Failed,{},e.what()});}
      catch(...) {finish_signboard_request(token,{Status::Failed,{},"ファイル選択を開始できませんでした"});}
    return true;
}

void YadoCreater::finish_signboard_request(const std::shared_ptr<int>& token,::cw::lib::documents::Result result)
{
    using namespace ::cw::lib::documents;
    if(m_image_request_token!=token) return;
    struct Release {
        YadoCreater& owner;std::shared_ptr<int> token;
        ~Release(){if(owner.m_image_request_token==token) {
            owner.m_image_request_token.reset();owner.m_image_ticket.reset();owner.request_dialog_presentation_refresh();
        }}
    } release{*this,token};
    if(m_presentation_finished || !visible) return;
    if(result.status==Status::Cancelled) return;
    try {
        if(result.status==Status::Success && result.documents.size()==1) {
            const auto& document=result.documents.front();
            if(document.kind!=LocationKind::NativePath) {
                result.error="この環境のプロバイダー画像取込みはまだ未対応です";
            } else if(set_signboard(document.location,document.access)) return;
            else result.error="選択したファイルは対応する看板画像ではありません";
        }
    } catch(const std::exception& e) {result.error=e.what();}
      catch(...) {result.error="画像の取得に失敗しました";}
    m_image_error=result.error.empty()?"ファイル選択に失敗しました":result.error;
    create_play_sound("error");
    (void)::cw::dialog::message::show_common_modal_message("看板画像の選択",m_image_error,false,true);
}

void YadoCreater::OnDelImage(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if(m_presentation_finished || image_request_pending() || m_save_pending || m_skin_popup || !visible) return;
    if(yado_composing()) return;
    create_play_sound("dump");
    m_imgpaths_typed.clear();
    m_imgpaths=Integer{0};m_signboard_access.reset();request_dialog_presentation_refresh();
}

void YadoCreater::OnDropFiles(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!arg_event) return;
    // 従来の単一パスのイベント用。実際の共通ホストからのドロップは常に vector
    // を渡す。 セミコロンや改行でファイル名を分割して一覧を作らない。
    dialog_presentation_drop_files({arg_event->title});
}
void YadoCreater::dialog_presentation_drop_files(const std::vector<std::string>& paths)
{
    if(m_presentation_finished || image_request_pending() || m_save_pending || m_skin_popup || !visible || paths.empty()) return;
    if(yado_composing()) return;
    for (const auto& path:paths) {
        if(path.empty() || path.find('\0')!=String::npos) continue;
        auto ext = std::get<1>(::cw::util::splitext(path));
        std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
        bool image = false;
        std::apply([&](const auto&... value) { ((image = image || ext == value), ...); }, ::cw::g_EXTS_IMG);
        if (image && set_signboard(path)) return; // Python と同様、対応する最初のファイルを選択する。
    }
    create_play_sound("error");
}

void YadoCreater::OnInput(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(m_presentation_finished || image_request_pending() || m_save_pending || m_skin_popup || !visible) return;
    if (arg_event) m_textctrl = arg_event->title;
    sync_name_input();
    m_okbtn = ::cw::lib::Value(!yado_edit_name(m_textctrl,m_name).empty());
    request_dialog_presentation_refresh();
}

void YadoCreater::OnChoice(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(m_presentation_finished || image_request_pending() || m_save_pending || !visible) return;
    if(yado_composing()) return;
    if(!arg_event) return;
    const auto found=std::find(m_skindirnames_typed.begin(),m_skindirnames_typed.end(),arg_event->title);
    if(found!=m_skindirnames_typed.end()) select_skin(static_cast<int>(found-m_skindirnames_typed.begin()));
}

void YadoCreater::open_skin_choice() {
    if(m_skindirnames_typed.empty()) return;
    m_input_focus=10;m_skin_popup=true;m_skin_search.reset();m_skin_hover_controls.clear();
    const auto found=std::find(m_skindirnames_typed.begin(),m_skindirnames_typed.end(),m_skindirname);
    m_skin_cursor=found==m_skindirnames_typed.end()?0:static_cast<int>(found-m_skindirnames_typed.begin());
    m_skin_offset=std::max(0,m_skin_cursor-5);
}
void YadoCreater::select_skin(int index) {
    if(index<0 || static_cast<std::size_t>(index)>=m_skindirnames_typed.size()) return;
    const auto& dirname=m_skindirnames_typed[index];
    if(dirname!=m_skindirname) create_play_sound("page");
    // ディレクトリーの識別情報は、表示名 Name と自動読み込みの真偽値とは分けて扱う。
    m_skindirname=dirname;m_skin=dirname;m_skin_cursor=index;m_skin_popup=false;
    request_dialog_presentation_refresh(); // CAUTION と既定の COMMAND0 は、新しい選択を使う。
}
void YadoCreater::move_skin_choice(int amount) {
    const int count=static_cast<int>(m_skindirnames_typed.size());
    if(!count) {m_skin_popup=false;return;}
    if(!m_skin_popup) {
        const auto found=std::find(m_skindirnames_typed.begin(),m_skindirnames_typed.end(),m_skindirname);
        m_skin_cursor=found==m_skindirnames_typed.end()?0:static_cast<int>(found-m_skindirnames_typed.begin());
    }
    m_skin_cursor=std::clamp(m_skin_cursor+std::clamp(amount,-count,count),0,count-1);
    if(!m_skin_popup) select_skin(m_skin_cursor);
    request_dialog_presentation_refresh();
}
void YadoCreater::dialog_presentation_scroll(float x,float y,int lines) {
    if(m_presentation_finished || image_request_pending() || m_save_pending || !visible || !lines) return;
    if(yado_composing()) return;
    if(name_menu_active()) {m_name_menu.scroll(lines,m_name_edit);request_dialog_presentation_refresh();return;}
    if(m_skin_popup || yado_contains(yado_layout(*this).skin,x,y)) move_skin_choice(lines);
}

void YadoCreater::OnOk(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    m_save_pending=true;m_save_error.clear();request_dialog_presentation_refresh();
    struct Release {YadoCreater& owner;~Release(){owner.m_save_pending=false;owner.request_dialog_presentation_refresh();}} release{*this};
    if(m_create) create_yado();else edit_yado();
    m_modal_result_ok=true;m_modal_closed=true;m_presentation_finished=true;visible=false;
    m_signboard_access.reset();
}

void YadoCreater::OnCancel(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    m_signboard_access.reset();
    create_play_sound("click");
    m_modal_result_ok = false;
    m_modal_closed = true;
    m_presentation_finished = true;
    visible = false;
}

std::shared_ptr<::cw::lib::Bitmap> YadoCreater::_load_caution()
{
    const auto index = [&] {
        const auto it = std::find(m_skindirnames_typed.begin(), m_skindirnames_typed.end(), m_skindirname);
        return it == m_skindirnames_typed.end()
                   ? std::size_t{0}
                   : static_cast<std::size_t>(std::distance(m_skindirnames_typed.begin(), it));
    }();
    if (index < m_cautionpaths_typed.size() && !m_cautionpaths_typed[index].empty())
        return ::cw::util::load_wxbmp(m_cautionpaths_typed[index], false, {}, {}, std::nullopt, true, true, false, std::nullopt);
    return ::cw::util::empty_bitmap(1, 1);
}

