// この表示プロバイダーは YadoCreater
// の保存モデルから直接データを受け取る。
// 全ホストで唯一のコントロール配置として
// 使い、UI の実装を共通の一つに保つ。
::cw::dialog::DialogPresentation YadoCreater::dialog_presentation()
{
    using Action = ::cw::dialog::DialogPresentationAction;
    namespace input=::cw::dialog::input_presentation;
    const auto px=[](Integer n){return ::cw::lib::ui::win_i(n);};
    const auto layout=yado_layout(*this);
    const auto width=layout.size.width,height=layout.size.height;
    m__inputareaheight=layout.input_height;
    sync_name_input();
    String skin_label=m_skindirname;
    const auto selected_skin=std::find(m_skindirnames_typed.begin(),m_skindirnames_typed.end(),m_skindirname);
    if(selected_skin!=m_skindirnames_typed.end()) {
        const auto index=static_cast<std::size_t>(selected_skin-m_skindirnames_typed.begin());
        if(index<m_skinlabels_typed.size() && !m_skinlabels_typed[index].empty()) skin_label=m_skinlabels_typed[index];
    }
    auto& retained=dialog_retained_surface();
    std::uint64_t base_signature=std::hash<String>{}(m_skindirname);
    const auto old_base=retained.component_signatures.find("yado.base");
    if(old_base!=retained.component_signatures.end() && old_base->second!=base_signature)retained.invalidate_all();
    const bool full=retained.needs_full(layout.size);
    if(full) {
        retained.allocate(layout.size,{240,240,240,255});
        const auto caution=::cw::lib::ui::resource_surface_for_window(_load_caution());
        if(caution && caution->size.width>0 && caution->size.height>0)
            for(Integer y=0;y<height;y+=caution->size.height)
                for(Integer x=0;x<width;x+=caution->size.width)
                    ::cw::lib::ui::blend_surface(retained.surface,caution,x,y);
        draw_yado_text(retained.surface,layout.message1,layout.message_x,px(10));
        draw_yado_text(retained.surface,layout.message2,layout.message_x,layout.message2_y);
        retained.component_signatures["yado.base"]=base_signature;
        retained.capture_base();
    }
    const auto mix=[](std::uint64_t& seed,std::uint64_t value){seed^=value+0x9e3779b97f4a7c15ULL+(seed<<6U)+(seed>>2U);};
    const bool blocked=image_request_pending()||m_save_pending||m_presentation_finished||!visible;
    std::uint64_t preview_signature=static_cast<std::uint64_t>(blocked);
    mix(preview_signature,std::hash<String>{}(m_skindirname));
    for(const auto& info:m_imgpaths_typed)if(info){mix(preview_signature,std::hash<String>{}(info->m_path));mix(preview_signature,std::hash<String>{}(info->m_postype));}
    mix(preview_signature,static_cast<std::uint64_t>(m_skin_popup));mix(preview_signature,static_cast<std::uint64_t>(name_menu_active()));
    std::uint64_t name_signature=std::hash<String>{}(m_name_edit.text);mix(name_signature,std::hash<String>{}(m_name_edit.composition));
    mix(name_signature,m_name_edit.caret);mix(name_signature,m_name_edit.anchor);mix(name_signature,static_cast<std::uint64_t>(m_name_edit.horizontal));
    mix(name_signature,static_cast<std::uint64_t>(m_input_focus));mix(name_signature,static_cast<std::uint64_t>(blocked));
    mix(name_signature,static_cast<std::uint64_t>(m_skin_popup));mix(name_signature,static_cast<std::uint64_t>(name_menu_active()));
    std::uint64_t skin_signature=std::hash<String>{}(skin_label);mix(skin_signature,static_cast<std::uint64_t>(m_input_focus));
    mix(skin_signature,static_cast<std::uint64_t>(blocked));mix(skin_signature,static_cast<std::uint64_t>(m_skin_popup));
    mix(skin_signature,static_cast<std::uint64_t>(name_menu_active()));
    std::uint64_t check_signature=static_cast<std::uint64_t>(m_is_autoloadparty);mix(check_signature,static_cast<std::uint64_t>(m_input_focus));
    mix(check_signature,static_cast<std::uint64_t>(blocked));mix(check_signature,static_cast<std::uint64_t>(m_skin_popup));
    mix(check_signature,static_cast<std::uint64_t>(name_menu_active()));
    const bool name_ready=!yado_edit_name(m_textctrl,m_name).empty();
    std::uint64_t footer_signature=static_cast<std::uint64_t>(name_ready);mix(footer_signature,static_cast<std::uint64_t>(m_input_focus));
    mix(footer_signature,static_cast<std::uint64_t>(blocked));mix(footer_signature,static_cast<std::uint64_t>(m_skin_popup));
    mix(footer_signature,static_cast<std::uint64_t>(name_menu_active()));
    const auto preview_left=std::min(layout.preview.x,layout.reference.x),preview_top=std::min(layout.preview.y,layout.reference.y);
    const auto preview_right=std::max(layout.preview.x+layout.preview.width,layout.reference.x+layout.reference.width);
    const auto preview_bottom=std::max(layout.preview.y+layout.preview.height,layout.reference.y+layout.reference.height);
    const bool paint_preview=retained.component_changed("yado.preview",{preview_left,preview_top,preview_right-preview_left,preview_bottom-preview_top},preview_signature);
    // ラベルと入力欄の組ごとにだけ復元する。 幅全体の更新帯では看
    // 板を横切り、その構成要素を更新対象にしないまま消してしまう。
    const Integer name_left=std::min(layout.label_x,layout.name.x);
    const Integer name_right=std::max(layout.label_x+layout.name_label.width,
                                      layout.name.x+layout.name.width);
    const Integer skin_left=std::min(layout.label_x,layout.skin.x);
    const Integer skin_right=std::max(layout.label_x+layout.skin_label.width,
                                      layout.skin.x+layout.skin.width);
    const bool paint_name=retained.component_changed("yado.name",
        {name_left,layout.name.y,name_right-name_left,layout.name.height},name_signature);
    const bool paint_skin=retained.component_changed("yado.skin",
        {skin_left,layout.skin.y,skin_right-skin_left,layout.skin.height},skin_signature);
    const bool paint_check=retained.component_changed("yado.autoload",layout.autoload,check_signature);
    const Integer footer_y=std::min(layout.ok.y,layout.cancel.y);
    const bool paint_footer=retained.component_changed("yado.footer",{0,footer_y,width,height-footer_y},footer_signature);
    std::vector<String> popup_labels=m_skindirnames_typed;
    for(std::size_t i=0;i<popup_labels.size()&&i<m_skinlabels_typed.size();++i)if(!m_skinlabels_typed[i].empty())popup_labels[i]=m_skinlabels_typed[i];
    ::cw::lib::Rect popup_rect{};bool paint_popup=false;
    if(m_skin_popup&&!popup_labels.empty()) {
        popup_rect=create_choice_popup_geometry(layout.size,popup_labels,layout.skin,m_skin_cursor,m_skin_offset,
            layout.combo_font,yado_choice_row_height(layout),6,true,std::max(1.0,::cw::g_UP_WIN));
        std::uint64_t popup_signature=static_cast<std::uint64_t>(m_skin_cursor+1);mix(popup_signature,static_cast<std::uint64_t>(m_skin_offset+1));
        paint_popup=retained.component_changed("yado.skin.popup",popup_rect,popup_signature);
    } else (void)retained.remove_component("yado.skin.popup");
    const auto menu_font=::cw::lib::ui::configured_wx_font("menu",13);
    const auto menu_rect=m_name_menu.presentation_bounds(layout.size,std::max(1.0,::cw::g_UP_WIN),menu_font);
    bool paint_name_menu=false;
    if(name_menu_active()) paint_name_menu=retained.component_changed("yado.name.menu",menu_rect,m_name_menu.presentation_signature(m_name_edit));
    else (void)retained.remove_component("yado.name.menu");
    retained.restore_dirty();
    auto surface=retained.surface;

    ::cw::dialog::DialogPresentation result;
    result.route="YADOCREATE";
    result.title=m_create?message_or("create_base_title","宿の作成"):message_or("edit_base_title","宿の編集");
    const auto hit=[&](Action action,int index,const ::cw::lib::Rect& rect,bool enabled,const String& label,const String& tooltip=String{}) {
        result.controls.push_back({action,index,static_cast<float>(rect.x),static_cast<float>(rect.y),
            static_cast<float>(rect.width),static_cast<float>(rect.height),enabled,false,label,tooltip});
    };
    const auto button=[&](const String& text,const ::cw::lib::Rect& rect,Action action,int index,bool enabled,
                           const String& tooltip=String{},const std::shared_ptr<::cw::lib::Surface>& icon=nullptr,bool paint=true) {
        if(paint) {
        ::cw::lib::ui::draw_button_face(surface,rect,{enabled});
        auto content=std::make_shared<::cw::lib::Surface>();content->size={rect.width-px(4),rect.height-px(4)};
        content->rgba.assign(static_cast<std::size_t>(content->size.width*content->size.height)*4,0);
        const auto font=::cw::lib::ui::configured_wx_font("button",rect.width<px(30)?12:14);
        const auto image=icon?icon: ::cw::lib::ui::render_label(text,font.pixels,font.bold,
            enabled?std::tuple<Integer,Integer,Integer>{0,0,0}:std::tuple<Integer,Integer,Integer>{100,100,100},font.face,font.italic);
        if(image) ::cw::lib::ui::blend_surface(content,image,
            (content->size.width-image->size.width)/2,(content->size.height-image->size.height)/2);
        ::cw::lib::ui::blend_surface(surface,content,rect.x+px(2),rect.y+px(2));
        }
        hit(action,index,rect,enabled,text,tooltip);
        result.controls.back().hover_highlight=true;
    };

    // Python と同様、すべての ImageInfo を SIZE_CARDIMAGE で切
    // り取る。 最初の画像を別のプレビュー矩形へ引き伸ばしたり、後続のレイヤーを捨てたりしない。
    if(paint_preview) {
    auto preview=std::make_shared<::cw::lib::Surface>();preview->size={layout.preview.width,layout.preview.height};
    preview->rgba.assign(static_cast<std::size_t>(preview->size.width*preview->size.height)*4,0);
    if(!m_imgpaths_typed.empty()) {
        for(const auto& info:m_imgpaths_typed) {
            if(!info || info->m_path.empty()) continue;
            const auto bitmap=::cw::lib::ui::resource_surface_for_window(::cw::util::load_wxbmp(
                info->m_path,true,{},{},std::nullopt,true,true,false,std::nullopt));
            if(!bitmap) continue;
            const auto pos=info->calc_basecardposition_wx({bitmap->size.width,bitmap->size.height},false,
                String("Bill"),String("NotCard"));
            ::cw::lib::ui::blend_surface(preview,bitmap,pos.x,pos.y);
        }
    } else {
        const auto selected=std::find(m_skindirnames_typed.begin(),m_skindirnames_typed.end(),m_skindirname);
        const auto index=selected==m_skindirnames_typed.end()?0U:static_cast<std::size_t>(selected-m_skindirnames_typed.begin());
        if(index<m_command0paths_typed.size() && !m_command0paths_typed[index].empty())
            ::cw::lib::ui::blend_surface(preview,::cw::lib::ui::resource_surface_for_window(
                ::cw::util::load_wxbmp(m_command0paths_typed[index],true,{},{},std::nullopt,true,true,false,std::nullopt)),0,0);
    }
    ::cw::lib::ui::blend_surface(surface,preview,layout.preview.x,layout.preview.y);
    }
    const bool custom_image=!m_imgpaths_typed.empty();
    const auto delete_icon=custom_image?::cw::lib::ui::resource_surface_for_window(
        ::cw::lib::ui::resource_dialog_surface("DELETE_FILE")):nullptr;
    button(custom_image?"×":"...",layout.reference,Action::Auxiliary,custom_image?2:1,true,
        custom_image?message_or("delete_signboard","看板画像を削除"):message_or("select_signboard","看板画像を選択")+"...",delete_icon,paint_preview);

    const auto& name=m_name_edit.text;
    const auto& name_rect=layout.name;
    if(paint_name) draw_yado_text(surface,layout.name_label,layout.label_x,name_rect.y+(name_rect.height-layout.name_label.height)/2);
    const bool name_focused=m_input_focus==0 && !image_request_pending() && !m_save_pending && !m_presentation_finished && visible;
    if(paint_name) input::field(surface,name_rect,m_name_edit,layout.input_font,name_focused);
    hit(Action::Select,0,name_rect,true,name,message_or("input_name","宿の名前"));
    result.controls.back().continuous_pointer=true;

    const auto& skin_rect=layout.skin;
    const auto& combo_font=layout.combo_font;
    if(paint_skin) {
    draw_yado_text(surface,layout.skin_label,layout.label_x,skin_rect.y+(skin_rect.height-layout.skin_label.height)/2);
    ::cw::lib::ui::fill_rect(surface,skin_rect,{255,255,255,255});
    auto skin_text=std::make_shared<::cw::lib::Surface>();skin_text->size={skin_rect.width-px(26),skin_rect.height-px(4)};
    skin_text->rgba.assign(static_cast<std::size_t>(skin_text->size.width*skin_text->size.height)*4,255);
    ::cw::lib::ui::draw_label(skin_text,skin_label,0,std::max<Integer>(0,(skin_text->size.height-input::cell_height(combo_font))/2),
        combo_font.pixels,combo_font.bold,{0,0,0},combo_font.face,combo_font.italic);
    ::cw::lib::ui::blend_surface(surface,skin_text,skin_rect.x+px(4),skin_rect.y+px(2));
    const Integer arrow_x=skin_rect.x+skin_rect.width-px(20),arrow_y=skin_rect.y+skin_rect.height/2-px(2);
    ::cw::lib::ui::fill_rect(surface,{arrow_x,skin_rect.y+1,px(20)-1,skin_rect.height-2},{240,240,240,255});
    for(int line=0;line<4;++line) ::cw::lib::ui::fill_rect(surface,{arrow_x+px(7+line),arrow_y+px(line),px(7-2*line),px(1)},
        m_skindirnames_typed.empty()?::cw::lib::Color{150,150,150,255}: ::cw::lib::Color{0,0,0,255});
    ::cw::lib::ui::draw_sunken_border(surface,skin_rect);
    }
    hit(Action::Auxiliary,10,skin_rect,!m_skindirnames_typed.empty(),skin_label,message_or("select_skin","スキン"));

    const auto& check=layout.autoload;
    const ::cw::lib::Rect box{check.x,check.y+(check.height-px(15))/2,px(15),px(15)};
    if(paint_check) {
    ::cw::lib::ui::draw_checkbox(surface,box,m_is_autoloadparty);
    draw_yado_text(surface,layout.check_label,check.x+px(22),check.y+(check.height-layout.check_label.height)/2);
    }
    hit(Action::Toggle,0,check,true,message_or("autoload_party","パーティを自動選択"),
        message_or("autoload_party_description","最後に選択していたパーティを自動選択します"));

    button(message_or("entry_decide","決定"),layout.ok,Action::Accept,0,name_ready,{},nullptr,paint_footer);
    button(message_or("entry_cancel","中止"),layout.cancel,Action::Cancel,0,true,{},nullptr,paint_footer);
    const bool skin_focused=m_input_focus==10 && !m_skindirnames_typed.empty();
    result.wants_text_input = name_focused;
    result.text_input_hardware_only=skin_focused;
    result.input_text = skin_focused?String{}:name;
    if(name_focused) {
        result.composition=m_name_edit.composition;result.composition_start=m_name_edit.composition_start;
        result.composition_length=m_name_edit.composition_length;
    }
    if(image_request_pending() || m_save_pending || m_presentation_finished || !visible) {
        result.wants_text_input=false;
        for(auto& control:result.controls) control.enabled=false;
    }

    if(m_input_focus!=0) for(const auto& control:result.controls) {
        const bool focused=m_input_focus==1?control.action==Action::Auxiliary && (control.index==1 || control.index==2):
            m_input_focus==10?control.action==Action::Auxiliary && control.index==10:
            m_input_focus==11?control.action==Action::Toggle:
            m_input_focus==12?control.action==Action::Accept:control.action==Action::Cancel;
        const bool paint_focus=m_input_focus==1?paint_preview:m_input_focus==10?paint_skin:
            m_input_focus==11?paint_check:paint_footer;
        if(!paint_focus || !focused || !control.enabled) continue;
        const int x=static_cast<int>(control.x+px(3)),y=static_cast<int>(control.y+px(3));
        const int right=static_cast<int>(control.x+control.width-px(4)),bottom=static_cast<int>(control.y+control.height-px(4));
        for(int px=x;px<=right;px+=2) for(int py:{y,bottom})
            ::cw::lib::ui::fill_rect(surface,{px,py,1,1},{0,0,0,255});
        for(int py=y;py<=bottom;py+=2) for(int px:{x,right})
            ::cw::lib::ui::fill_rect(surface,{px,py,1,1},{0,0,0,255});
    }
    if(m_skin_popup && m_skindirnames_typed.empty()) m_skin_popup=false;
    if(m_skin_popup) {
        draw_create_choice_popup(result,surface,popup_labels,skin_rect,m_skin_cursor,m_skin_offset,combo_font,
            yado_choice_row_height(layout),6,true,std::max(1.0,::cw::g_UP_WIN),paint_popup);
        if(image_request_pending() || m_save_pending || m_presentation_finished || !visible)
            for(auto& control:result.controls) control.enabled=false;
    }
    if(skin_focused && visible && !m_presentation_finished && !image_request_pending() && !m_save_pending)
        result.wants_text_input=true; // 読み取り専用の選択欄での入力検索として扱い、ソフトキーボードやテキスト欄は使わない。
    if(name_menu_active()) {
        result.wants_text_input=false;
        m_name_menu.draw(result,surface,m_name_edit,std::max(1.0,::cw::g_UP_WIN),menu_font,paint_name_menu);
    }
    retained.finish();result.surface=surface;result.damage=retained.damage;result.surface_revision=retained.revision;
    m_skin_hover_controls=m_skin_popup?result.controls:std::vector<::cw::dialog::DialogPresentationControl>{};
    return result;
}

void YadoCreater::dialog_presentation_action(
    const ::cw::dialog::DialogPresentationAction action, const int index)
{
    using Action = ::cw::dialog::DialogPresentationAction;
    if (m_presentation_finished || image_request_pending() || m_save_pending || !visible) return;
    dialog_presentation_pointer_cancel();
    if(name_menu_active()) {
        m_name_menu.action(action,index,m_name_edit,[this]{return read_name_clipboard();},
            [this](const String& value){write_name_clipboard(value);},18);
        publish_name_input();request_dialog_presentation_refresh();return;
    }
    if(::cw::dialog::textedit::EditMenu::is_control(action,index)) return;
    // Py のネイティブ文字入力・選択ウィジェットは、ダイアログのボタンイベントより前に IME
    // の変換とポップアップの終了を処理する。 共通キャンバスでは、その境界をここで処理する。
    if(yado_composing()) {
        if(action==Action::Cancel) {
            m_name_edit.set_composition("");m_skin_search.reset();
            request_dialog_presentation_refresh();
        }
        return;
    }
    m_skin_search.reset();

    if(m_skin_popup) {
        if(action==Action::Cancel || (action==Action::Auxiliary && index==10)) m_skin_popup=false;
        else if(action==Action::Accept) select_skin(m_skin_cursor);
        else if(action==Action::Auxiliary && index>=100) select_skin(index-100);
        else if(action==Action::Auxiliary && (index==98 || index==99)) move_skin_choice(index==98?-1:1);
        request_dialog_presentation_refresh();return;
    }
    if(action==Action::Select && index==0) {sync_name_input();m_input_focus=0;request_dialog_presentation_refresh();return;}
    if (action == Action::Accept) {
        if(!yado_edit_name(m_textctrl,m_name).empty()) OnOk(nullptr);
    } else if (action == Action::Cancel) {
        OnCancel(nullptr);
    } else if (action == Action::Toggle) {
        m_input_focus=11;
        m_is_autoloadparty=!m_is_autoloadparty;
    } else if (action == Action::Auxiliary && index == 1) {
        m_input_focus=1;
        request_signboard();
    } else if (action == Action::Auxiliary && index == 2) {
        m_input_focus=1;
        OnDelImage(nullptr);
    } else if(action==Action::Auxiliary && index==10) {
        open_skin_choice();
    }
    request_dialog_presentation_refresh();
}

void YadoCreater::sync_name_input() {
    const auto name=value_string(m_textctrl,m_name);
    if(name!=m_name_edit.text) {m_name_menu.close();m_name_dragging=false;m_name_edit.reset(name,false,false);}
}
void YadoCreater::publish_name_input() {
    m_textctrl=m_name_edit.text;OnInput(nullptr);
}
String YadoCreater::read_name_clipboard() const {return ::cw::dialog::presentation_clipboard_text();}
void YadoCreater::write_name_clipboard(const String& text) {::cw::dialog::presentation_set_clipboard_text(text);}

void YadoCreater::dialog_presentation_text(const std::string& text,const bool composition)
{
    if(name_menu_active()) return;
    if(m_presentation_finished || image_request_pending() || m_save_pending || !visible) return;
    if(m_input_focus==10 && !m_skindirnames_typed.empty()) {
        // 共通ホストは、コマンドキーとは別に UTF-8 文字列を一度だけ渡す。
        if(!composition && (text=="\b" || (text==" " && !m_skin_search.active()))) return;
        m_skin_search.composing=composition && !text.empty();
        if(composition) return;
        if(m_name_modifiers & (::cw::dialog::DialogPresentationModifierControl|::cw::dialog::DialogPresentationModifierAlt)) {
            m_skin_search.reset();return;
        }
        const auto found=std::find(m_skindirnames_typed.begin(),m_skindirnames_typed.end(),m_skindirname);
        const int current=m_skin_popup?m_skin_cursor:static_cast<int>(found-m_skindirnames_typed.begin());
        const auto row=m_skin_search.find(text,static_cast<int>(m_skindirnames_typed.size()),current,[&](int i) {
            return i<static_cast<int>(m_skinlabels_typed.size()) && !m_skinlabels_typed[i].empty()
                ?m_skinlabels_typed[i]:m_skindirnames_typed[i];
        });
        if(row) {
            if(m_skin_popup) m_skin_cursor=*row;else select_skin(*row);
            request_dialog_presentation_refresh();
        }
        return;
    }
    if(m_input_focus!=0) return;
    sync_name_input();
    if(composition) {m_name_dragging=false;m_name_edit.set_composition(text);}
    else {
        if(text=="\b" && !m_name_edit.composition.empty()) return;
        m_name_edit.insert(text,18,false);publish_name_input();
    }
    request_dialog_presentation_refresh();
}
void YadoCreater::dialog_presentation_text_event(const ::cw::dialog::DialogTextEditingEvent& event) {
    if(name_menu_active()) return;
    if(m_presentation_finished || image_request_pending() || m_save_pending || !visible ||
        (m_input_focus!=0 && m_input_focus!=10)) return;
    ::cw::dialog::DialogPresentationProvider::dialog_presentation_text_event(event);
    if(event.composition && m_input_focus==0) m_name_edit.set_composition(event.text,event.start,event.length);
}
void YadoCreater::dialog_presentation_pointer(::cw::dialog::DialogPresentationAction action,int index,
    float x,float y,bool pressed) {
    if(name_menu_active()) {if(!pressed) dialog_presentation_action(action,index);return;}
    if(m_presentation_finished || image_request_pending() || m_save_pending || !visible) return;
    if(yado_composing()) return;
    if(m_skin_popup) {if(!pressed) dialog_presentation_action(action,index);return;}
    if(action!=::cw::dialog::DialogPresentationAction::Select || index!=0) {
        if(!pressed) dialog_presentation_action(action,index);
        return;
    }
    if(!std::isfinite(x) || !std::isfinite(y)) return;
    sync_name_input();
    if(!m_name_edit.composition.empty() || (!pressed && !m_name_dragging)) return;
    const auto layout=yado_layout(*this);
    const auto pos=::cw::dialog::input_presentation::caret_at(m_name_edit,layout.name,layout.input_font,x);
    m_input_focus=0;m_name_edit.move(pos,m_name_dragging || (m_name_modifiers & ::cw::dialog::DialogPresentationModifierShift));m_name_dragging=pressed;
    request_dialog_presentation_refresh();
}
void YadoCreater::dialog_presentation_pointer_cancel() {m_name_dragging=false;}

bool YadoCreater::name_menu_active()
{
    if(!m_name_menu.opened()) return false;
    sync_name_input();
    if(m_presentation_finished || m_modal_closed || image_request_pending() || m_save_pending || !visible || m_skin_popup || m_input_focus!=0) m_name_menu.close();
    return m_name_menu.opened();
}
void YadoCreater::open_name_menu(float x,float y,bool keyboard)
{
    sync_name_input();
    if(m_presentation_finished || m_modal_closed || image_request_pending() || m_save_pending || !visible || m_skin_popup || m_input_focus!=0 || !m_name_edit.composition.empty()) return;
    m_name_dragging=false;
    if(keyboard) {
        const auto layout=yado_layout(*this);
        const auto point=::cw::dialog::input_presentation::menu_anchor(m_name_edit,layout.name,layout.input_font);
        x=static_cast<float>(point.x);y=static_cast<float>(point.y);
    }
    m_name_menu.open(m_name_edit,!read_name_clipboard().empty(),x,y,keyboard);
    request_dialog_presentation_refresh();
}
void YadoCreater::dialog_presentation_hover(float x,float y)
{
    if(m_presentation_finished || image_request_pending() || m_save_pending || !visible ||
       !std::isfinite(x) || !std::isfinite(y) || yado_composing()) return;
    if(name_menu_active()) {
        if(m_name_menu.hover(x,y,m_name_edit)) request_dialog_presentation_refresh();
        return;
    }
    if(!m_skin_popup) return;
    // 公開済みの当たり判定矩形を再利用し、ホバー時に再描画や画像読み込みを行わない。
    for(const auto& control:m_skin_hover_controls) {
        if(control.action!=::cw::dialog::DialogPresentationAction::Auxiliary || control.index<100 || !control.enabled) continue;
        if(x>=control.x && x<control.x+control.width && y>=control.y && y<control.y+control.height) {
            const int row=control.index-100;
            if(row!=m_skin_cursor) {m_skin_search.reset();m_skin_cursor=row;request_dialog_presentation_refresh();}
            return;
        }
    }
}

void YadoCreater::dialog_presentation_context(float x,float y) {
    if(name_menu_active()) {m_name_menu.close();request_dialog_presentation_refresh();return;}
    if(m_presentation_finished || m_modal_closed || image_request_pending() || m_save_pending || !visible || !std::isfinite(x) || !std::isfinite(y)) return;
    if(yado_composing()) {
        // テキスト欄のコンテキストクリックで、読み取り専用の選択欄から IME の処理を奪わない。
        if(!yado_contains(yado_layout(*this).name,x,y))
            dialog_presentation_action(::cw::dialog::DialogPresentationAction::Cancel,-1);
        return;
    }
    if(!m_skin_popup && yado_contains(yado_layout(*this).name,x,y)) {
        m_input_focus=0;
        open_name_menu(x,y);return;
    }
    dialog_presentation_action(::cw::dialog::DialogPresentationAction::Cancel,-1);
}
void YadoCreater::dialog_presentation_key(::cw::dialog::DialogPresentationKey key,bool pressed,
    ::cw::dialog::DialogPresentationModifiers modifiers) {
    using Key=::cw::dialog::DialogPresentationKey;
    using Action=::cw::dialog::DialogPresentationAction;
    if(!pressed || m_presentation_finished || image_request_pending() || m_save_pending || !visible) return;
    dialog_presentation_pointer_cancel();sync_name_input();
    m_name_modifiers=modifiers;
    if(name_menu_active()) {
        m_name_menu.key(key,modifiers,m_name_edit,[this]{return read_name_clipboard();},
            [this](const String& value){write_name_clipboard(value);},18);
        publish_name_input();request_dialog_presentation_refresh();return;
    }
    if(!m_skin_popup && m_input_focus==0 && !(modifiers & (::cw::dialog::DialogPresentationModifierControl|::cw::dialog::DialogPresentationModifierAlt)) &&
        (key==Key::ContextMenu || (key==Key::F10 && (modifiers & ::cw::dialog::DialogPresentationModifierShift)))) {
        open_name_menu(-1,-1,true);return;
    }

    if(key==Key::Escape) {dialog_presentation_action(Action::Cancel,-1);return;}
    if(yado_composing()) return;
    if(key==Key::Space && m_input_focus==10 && m_skin_search.active() && !modifiers) return;
    if(!::cw::dialog::presentation_key_ascii(key) ||
       (modifiers & (::cw::dialog::DialogPresentationModifierControl|::cw::dialog::DialogPresentationModifierAlt)))
        m_skin_search.reset();
    const bool ctrl=(modifiers & ::cw::dialog::DialogPresentationModifierControl)!=0;
    const bool shift=(modifiers & ::cw::dialog::DialogPresentationModifierShift)!=0;
    const bool alt=(modifiers & ::cw::dialog::DialogPresentationModifierAlt)!=0;
    if(!ctrl && m_input_focus==10 && ((alt && (key==Key::Down || key==Key::Up)) || (!alt && key==Key::F4))) {
        if(m_skin_popup) select_skin(m_skin_cursor);else open_skin_choice();
        request_dialog_presentation_refresh();return;
    }
    if(alt) return;
    if(m_skin_popup) {
        if(ctrl) return;
        if(key==Key::Enter || key==Key::Space || key==Key::Tab) {
            select_skin(m_skin_cursor);
            if(key!=Key::Tab) return;
        } else {
            if(key==Key::Up || key==Key::Left) move_skin_choice(-1);
            else if(key==Key::Down || key==Key::Right) move_skin_choice(1);
            else if(key==Key::Home) move_skin_choice(-static_cast<int>(m_skindirnames_typed.size()));
            else if(key==Key::End) move_skin_choice(static_cast<int>(m_skindirnames_typed.size()));
            else if(key==Key::PageUp || key==Key::PageDown) {
                const int rows=yado_choice_page_rows(yado_layout(*this));
                move_skin_choice(key==Key::PageUp?-rows:rows);
            }
            return;
        }
    }
    if(!ctrl && key==Key::Tab) {
        std::vector<int> order{0,1};
        if(!m_skindirnames_typed.empty()) order.push_back(10);
        order.push_back(11);
        if(!yado_edit_name(m_textctrl,m_name).empty()) order.push_back(12);
        order.push_back(13);
        const auto it=std::find(order.begin(),order.end(),m_input_focus);
        const auto pos=it==order.end()?0:static_cast<std::size_t>(it-order.begin());
        m_input_focus=order[(pos+order.size()+(shift?-1:1))%order.size()];
    } else if(!ctrl && (key==Key::Enter || (key==Key::Space && m_input_focus!=0))) {
        if(m_input_focus==13) OnCancel(nullptr);
        else if(m_input_focus==1) dialog_presentation_action(Action::Auxiliary,m_imgpaths_typed.empty()?1:2);
        else if(m_input_focus==10) dialog_presentation_action(Action::Auxiliary,10);
        else if(m_input_focus==11 && key==Key::Space) dialog_presentation_action(Action::Toggle,0);
        else dialog_presentation_action(Action::Accept,0);
    } else if(m_input_focus==0) {
        ::cw::dialog::textedit::single_line_key(m_name_edit,key,modifiers,18,
            [this]{return read_name_clipboard();},[this](const std::string& text){write_name_clipboard(text);});
        publish_name_input();
    } else if(m_input_focus==10 && !ctrl) {
        if(key==Key::Left || key==Key::Up) move_skin_choice(-1);
        else if(key==Key::Right || key==Key::Down) move_skin_choice(1);
        else if(key==Key::Home || key==Key::End) move_skin_choice((key==Key::Home?-1:1)*static_cast<int>(m_skindirnames_typed.size()));
        else if(key==Key::PageUp || key==Key::PageDown) {
            const int rows=yado_choice_page_rows(yado_layout(*this));
            move_skin_choice(key==Key::PageUp?-rows:rows);
        }
    }
    request_dialog_presentation_refresh();
}
void YadoCreater::dialog_presentation_enter(::cw::dialog::DialogPresentationModifiers modifiers) {
    dialog_presentation_key(::cw::dialog::DialogPresentationKey::Enter,true,modifiers);
}

bool YadoCreater::dialog_presentation_finished() const noexcept
{
    return m_presentation_finished || m_modal_closed || !visible;
}

void YadoCreater::dialog_presentation_complete()
{
    m_name_menu.close();m_name_modifiers=0;m_skin_search.reset();m_skin_hover_controls.clear();
    m_skin_popup=false;
    m_name_edit.composition.clear();m_name_dragging=false;
    m_image_request_token.reset();m_image_ticket.reset();
    m_signboard_access.reset();
    // 終了処理中にホストがモデルを既に非表示にしている場合もあるが、完了処理と取得した利用
    // 権の解放は行う。 OnCancel は非表示時の入力を無視するため、そこへ委ねない。
    if(!m_presentation_finished) {
        m_modal_result_ok=false;m_modal_closed=true;
        m_presentation_finished=true;visible=false;
    }
}

