::cw::lib::String create_description(::cw::lib::String arg_talent, const std::set<::cw::lib::String>& arg_attrs, ::cw::lib::String arg_desc)
{
    std::vector<::cw::lib::String> sections;
    const auto without_first = [](const String& value) {
        auto bytes = ::cw::lib::encoding::utf8_to_utf32(
            value, ::cw::lib::encoding::ByteOrder::Little);
        if (!bytes.empty()) bytes.erase(bytes.begin(), bytes.begin() + 4);
        return ::cw::lib::encoding::utf32_to_utf8(bytes,
            ::cw::lib::encoding::ByteOrder::Little,
            ::cw::lib::encoding::ErrorPolicy::Strict, false);
    };
    sections.push_back("　　　　　　　　" + without_first(arg_talent));
    ::cw::lib::String attributes;
    std::size_t index = 0;
    for (const auto& making : ::cw::setting::Setting::s_makingcoupons) {
        if (!arg_attrs.count(making)) continue;
        ::cw::lib::String s = without_first(making);
        const std::size_t n = index % 3;
        if (arg_attrs.size() != index + 1) {
            if (n == 2) s += "\n";
            else {
                const std::size_t chars = ::cw::lib::encoding::utf8_to_utf32(
                    s, ::cw::lib::encoding::ByteOrder::Little).size() / 4;
                for (std::size_t i = chars; i < 7; ++i) s += "　";
            }
        }
        attributes += s; ++index;
    }
    // Py は seq2 があれば、rstrip で内容がすべて消
    // えても属性の節を追加する。 結合時もその空の節を維持する。
    if (index != 0) sections.push_back(::cw::lib::python_rstrip(attributes));
    if (!arg_desc.empty()) sections.push_back(::cw::util::txtwrap(arg_desc, 4));
    ::cw::lib::String result;
    for (const auto& section : sections) { if (!result.empty()) result += "\n\n"; result += section; }
    return result;
}

