::cw::lib::String get_randomname(::cw::lib::String arg_sex)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata)
        throw std::logic_error("inn data is required for random names");
    auto names=creator_randomnames(arg_sex);
    if (names.empty()) return {};
    std::set<String> all = names;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata) for (const auto& standby : (*::cw::g_cwpy->m_ydata)->m_standbys) if (standby) names.erase(standby->m_name);
    if (names.empty()) names = std::move(all);
    // ネイティブの std::set の順序は一定だが、Py の set の走査順はプロセスごとに変わる。
    // このコンテナーの違いは維持しつつ、選択にはサイコロではなく Py の choice と同じ抽選を使う。
    std::vector<String> choices(names.begin(), names.end());
    return choices[::cw::dice::choice_index(choices.size())];
}

std::set<::cw::lib::String> _get_randomnamefromexample(::cw::lib::String arg_sex, ::cw::lib::String arg_skintype)
{
    std::set<String> names;
    const std::filesystem::path dir("Data/SkinBase/Name/Example");
    if (!std::filesystem::is_directory(dir)) return names;
    const std::vector<String> files = {"CommonNames.txt", arg_sex.empty() ? String{} : arg_sex + "Names.txt"};
    for (const auto& base : files) {
        if (base.empty()) continue;
        if (names.find(base) != names.end()) continue;
        const auto stem = std::get<0>(::cw::util::splitext(base));
        const auto prefix = stem + "_";
        for (const auto& entry : std::filesystem::directory_iterator(dir)) {
            const auto filename = ::cw::lib::encoding::path_to_utf8(entry.path().filename());
            if (filename.rfind(prefix, 0) != 0) continue;
            auto suffix = filename.substr(prefix.size());
            suffix = std::get<0>(::cw::util::splitext(suffix));
            const String lower = ::cw::lib::encoding::lower(suffix);
            const String type = ::cw::lib::encoding::lower(arg_skintype);
            bool match = false; std::stringstream stream(lower); String token;
            while (std::getline(stream, token, '+')) if (token == type) match = true;
            if (match) names.merge(_read_names(::cw::lib::encoding::path_to_utf8(entry.path())));
        }
    }
    return names;
}

std::set<::cw::lib::String> _read_names(::cw::lib::String arg_fpath)
{
    std::set<String> names;
    try {
        const auto path = std::filesystem::u8path(arg_fpath);
        if (!std::filesystem::is_regular_file(path)) return names;
        const auto bytes = ::cw::lib::FileSystem::read_binary(path);
        // str.splitlinesの規則で分割し、前後の空白を取り除
        // く。#で始まるコメント行を除外し、空行は空文字列として残す。
        for (auto line : ::cw::lib::encoding::splitlines(::cw::util::decode_text(bytes))) {
            line = ::cw::lib::python_strip(line);
            if (line.empty() || line.front() != '#') names.insert(line);
        }
    } catch (...) {
        // Python版の cw.util.print_ex() と同様、名前ファイルの読込み失敗を診断へ残す。
        ::cw::util::print_ex(std::nullopt);
    }
    return names;
}

