std::map<std::tuple<::cw::lib::String, ::cw::lib::String>, ::cw::lib::String> _get_randommakingsandpair()
{
    std::map<std::tuple<String, String>, String> result;
    const auto nv = dice_roll(5);
    for (std::size_t i = 0; i < ::cw::setting::Setting::s_makingnames.size(); i += 2) {
        const auto& left = ::cw::setting::Setting::s_makingnames[i];
        const auto right = i + 1 < ::cw::setting::Setting::s_makingnames.size() ? ::cw::setting::Setting::s_makingnames[i+1] : String{};
        const auto pair_len = right.empty() ? Integer(1) : Integer(2);
        const auto n = dice_roll(pair_len + nv) - 1;
        if (n < pair_len) result[{left, right}] = "＿" + (n == 0 ? left : right);
    }
    return result;
}

std::set<::cw::lib::String> get_randommakings()
{
    std::set<String> result;
    for (const auto& [pair, value] : _get_randommakingsandpair()) result.insert(value);
    return result;
}

