::cw::lib::Integer _index_of(std::vector<std::shared_ptr<::cw::image::ImageInfo>> arg_imgpaths, std::vector<std::vector<std::shared_ptr<::cw::image::ImageInfo>>> arg_imgpathlist)
{
    const auto same = [](const auto& lhs, const auto& rhs) {
        if (lhs.size() != rhs.size()) return false;
        for (std::size_t i = 0; i < lhs.size(); ++i) {
            // Python のリストの等価比較は、__eq__ より先に要素の同一性を確認する。
            if (lhs[i] == rhs[i]) continue;
            if (!lhs[i] || !rhs[i]) throw std::invalid_argument("image list contains an invalid ImageInfo");
            if (lhs[i]->m_path != rhs[i]->m_path || lhs[i]->m_pcnumber != rhs[i]->m_pcnumber || lhs[i]->m_postype != rhs[i]->m_postype) return false;
        }
        return true;
    };
    for (std::size_t i = 0; i < arg_imgpathlist.size(); ++i) if (same(arg_imgpaths, arg_imgpathlist[i])) return static_cast<Integer>(i);
    // ネイティブの invalid_argument は、Python の list.index が出す ValueError に対応する。
    throw std::invalid_argument("image list is not in image group");
}

